function secondaryPathwayMatrixPanel(){if(level!=='secondary')return '';const ar=lang==='ar',fr=lang==='fr';const options=SECONDARY_PATHWAYS.filter(x=>x.grades.includes(grade));const chosen=options.find(x=>x.id===selectedSecondaryPathway);const matrix=chosen&&SECONDARY_PATHWAY_MATRIX.find(x=>x.pathway_id===chosen.id&&x.grade===grade);const title=ar?'دليل المواد حسب الجذع والشعبة':fr?'Repère des matières par tronc et filière':'Subject guide by common core and stream';const common=ar?'مواد مرشحة مشتركة':'Matières communes candidates';const spec=ar?'مواد مرشحة للتخصص':'Matières candidates de spécialité';const pending=ar?'قائمة تنظيمية أولية وليست جدولاً وزارياً معتمداً. يجب التحقق من المواد والساعات والمعاملات والتدرج السنوي من وثائق الوزارة 2026–2027.':'Provisional planning list, not an approved Ministry timetable. Subject inclusion, hours, coefficients and annual progression require verification against 2026–2027 Ministry documents.';const selector=`<label class="pathway-selector">${ar?'الجذع / الشعبة':fr?'Tronc / filière':'Common core / stream'}<select onchange="setSecondaryPathway(this.value)"><option value="">${ar?'اختر المسار':fr?'Choisir le parcours':'Choose pathway'}</option>${options.map(x=>`<option value="${x.id}" ${selectedSecondaryPathway===x.id?'selected':''}>${x[lang]||x.en}</option>`).join('')}</select></label>`;if(!matrix)return `<section class="panel pathway-matrix-panel"><h3>${title}</h3>${selector}<p>${ar?'اختر الجذع أو الشعبة لعرض قائمة المواد المرشحة.':fr?'Choisissez un tronc ou une filière pour afficher les matières candidates.':'Choose a common core or stream to view candidate subject areas.'}</p><p class="notice">${pending}</p></section>`;const renderItems=items=>items.map(x=>`<li>${x[lang]||x.en}</li>`).join('');return `<section class="panel pathway-matrix-panel"><h3>${title}</h3>${selector}<div class="pathway-matrix-columns"><div><b>${common}</b><ul>${renderItems(matrix.common_subject_candidates)}</ul></div><div><b>${spec}</b><ul>${renderItems(matrix.specialization_subject_candidates)}</ul></div></div><p class="notice">${pending}</p><small>${ar?'المسار: ':fr?'Parcours : ':'Pathway: '}${chosen[lang]||chosen.en} · ${ar?'السنة: ':fr?'Niveau : ':'Grade: '}${grade}</small></section>`;}
let selectedSecondaryPathway=localStorage.getItem('smSchoolSecondaryPathway')||'';
function setSecondaryPathway(value){selectedSecondaryPathway=value;localStorage.setItem('smSchoolSecondaryPathway',value);if(page==='exercises')renderExerciseBankHome();else if(page==='tests')renderTestBankHome();else render();}
function secondaryPathwayNotice(){if(level!=='secondary')return '';const ar=lang==='ar',fr=lang==='fr',items=SECONDARY_PATHWAYS.filter(x=>x.grades.includes(grade)),chosen=items.find(x=>x.id===selectedSecondaryPathway);const label=ar?'الجذع / الشعبة':fr?'Tronc / filière':'Common core / stream';return `<div class="panel secondary-pathway-panel"><label><b>${label}</b><select onchange="setSecondaryPathway(this.value)"><option value="">${ar?'اختر المسار':fr?'Choisir le parcours':'Choose pathway'}</option>${items.map(x=>`<option value="${x.id}" ${selectedSecondaryPathway===x.id?'selected':''}>${x[lang]||x.en}</option>`).join('')}</select></label><p class="notice">${ar?`فهرس تنظيمي فقط. ${chosen?'المحدد: '+chosen.ar+'. ':''}لم تُخصص التمارين للشعب بعد؛ ننتظر التحقق من جدول المواد الرسمي 2026–2027.`:fr?`Index de navigation uniquement. ${chosen?'Choix : '+chosen.fr+'. ':''}Les exercices ne sont pas encore affectés aux filières; validation ministérielle 2026–2027 requise.`:`Navigation index only. ${chosen?'Selected: '+chosen.en+'. ':''}Exercises are not yet assigned to streams; current Ministry subject-matrix verification is required.`}</p></div>`;}
