function subjectsForCurrentGrade(){const list=[...(subjects[level]||[])];if(level==='primary'){const n=levels.primary.indexOf(grade);if(n>=2)list.push('اللغة الإنجليزية');if(n>=3)list.push('اللغة الفرنسية');}return list;}
function curriculumNotice(){return lang==='ar'?`<div class="notice curriculum-notice"><b>المرجعية التربوية: ${ACADEMIC_YEAR}</b><br>يُراعى التدرج اللغوي المعلن: الإنجليزية من السنة الثالثة ابتدائي والفرنسية من الرابعة. أما تسلسل الدروس والكفاءات التفصيلي لكل مادة وسنة فيبقى قيد المطابقة مع وثائق الوزارة السنوية.</div>`:lang==='fr'?`<div class="notice curriculum-notice"><b>Référence pédagogique : ${ACADEMIC_YEAR}</b><br>Au primaire, l’anglais commence en 3e année et le français en 4e année. Les séquences détaillées par matière et niveau restent à vérifier avec les documents ministériels annuels.</div>`:`<div class="notice curriculum-notice"><b>Curriculum reference: ${ACADEMIC_YEAR}</b><br>In primary school, English starts in Year 3 and French in Year 4. Detailed subject-by-subject lesson sequences still require verification against the Ministry's annual documents.</div>`;}
const demoBank={primary:[{q:'احسب: 7 + 5 = ؟',choices:['10','12','13'],a:1,why:'7 + 5 = 12.'},{q:'ما العدد الذي يسبق 30؟',choices:['29','31','20'],a:0,why:'العدد السابق مباشرة لـ30 هو 29.'},{q:'كم ضلعاً للمربع؟',choices:['3','4','5'],a:1,why:'للمربع أربعة أضلاع متساوية.'}],middle:[{q:'احسب: 3/4 + 1/4 = ؟',choices:['1','1/2','4/8'],a:0,why:'(3+1)/4 = 4/4 = 1.'},{q:'حل المعادلة: x + 7 = 12',choices:['4','5','6'],a:1,why:'x = 12 - 7 = 5.'},{q:'مساحة مستطيل طوله 6 سم وعرضه 3 سم؟',choices:['9 سم²','18 سم²','12 سم²'],a:1,why:'المساحة = 6 × 3 = 18 سم².'}],secondary:[{q:'حل المعادلة: 2x + 5 = 13',choices:['3','4','5'],a:1,why:'2x = 8 ثم x = 4.'},{q:'مشتقة الدالة f(x)=x²؟',choices:['x','2x','x²'],a:1,why:'باستعمال قاعدة القوة تكون المشتقة 2x.'},{q:'احتمال حدث مؤكد؟',choices:['0','0.5','1'],a:2,why:'الحدث المؤكد احتماله يساوي 1.'}]};
