 'اللغة العربية':{primary:[{q:'اختر الاسم من الكلمات الآتية:',choices:['يكتب','مدرسة','جميل'],a:1,why:'مدرسة اسم يدل على مكان.'},{q:'ما جمع كلمة كتاب؟',choices:['كاتب','كتب','مكتبة'],a:1,why:'جمع كتاب هو كتب.'},{q:'أكمل: الشمس ...',choices:['مشرق','مشرقة','يشرق'],a:1,why:'مشرقة صفة مؤنثة توافق الشمس.'}],middle:[{q:'حدد الفعل الماضي:',choices:['يقرأ','اقرأ','قرأ'],a:2,why:'قرأ فعل ماضٍ يدل على حدث وقع.'},{q:'ما نوع الجملة: العلم نور؟',choices:['اسمية','فعلية','استفهامية'],a:0,why:'بدأت الجملة باسم، فهي جملة اسمية.'},{q:'مرادف كلمة شجاع:',choices:['جبان','جريء','كسول'],a:1,why:'جريء مرادف شجاع.'}],secondary:[{q:'ما نوع الصورة البيانية في: ابتسم الصباح؟',choices:['استعارة مكنية','تشبيه مفصل','كناية عن عدد'],a:0,why:'شُبّه الصباح بإنسان يبتسم وحُذف المشبه به.'},{q:'ما إعراب كلمة الطالب في: إن الطالب مجتهد؟',choices:['مبتدأ مرفوع','اسم إن منصوب','خبر إن مرفوع'],a:1,why:'اسم إن منصوب وعلامة نصبه الفتحة.'},{q:'أيّ مما يلي أسلوب توكيد؟',choices:['ما أجمل السماء!','إن الحق واضح','هل حضرت؟'],a:1,why:'إنّ من أدوات التوكيد.'}]},
