function calculateStudyStreak(items, today=new Date().toISOString().slice(0,10)){
  const dates=[...new Set((items||[]).map(x=>x.date).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x||'')))].sort();
  if(!dates.length)return {current:0,longest:0,days:0};
  const dayMs=86400000, dayNumber=s=>Math.floor(Date.parse(s+'T00:00:00Z')/dayMs);
  let longest=0,run=0,previous=null;
  for(const date of dates){const n=dayNumber(date);run=previous!==null&&n===previous+1?run+1:1;longest=Math.max(longest,run);previous=n;}
  const latest=dates[dates.length-1],gap=dayNumber(today)-dayNumber(latest);
  let current=0;
  if(gap===0||gap===1){let expected=dayNumber(latest);for(let i=dates.length-1;i>=0;i--){const n=dayNumber(dates[i]);if(n!==expected)break;current++;expected--;}}
  return {current,longest,days:dates.length};
}
function studyStreakPanel(items){
  const s=calculateStudyStreak(items),ar=lang==='ar',fr=lang==='fr';
  const labels=ar?{title:'الاستمرارية في الدراسة',current:'أيام متتالية حالية',best:'أفضل سلسلة',active:'أيام دراسة مسجلة',empty:'ابدأ أول نشاط دراسي لتظهر استمراريتك هنا.'}:fr?{title:'Régularité des études',current:'Série actuelle',best:'Meilleure série',active:'Jours d’étude enregistrés',empty:'Commencez une activité pour suivre votre régularité.'}:{title:'Study consistency',current:'Current streak',best:'Best streak',active:'Active study days',empty:'Complete a study activity to start tracking your streak.'};
  return `<section class="panel streak-panel"><div class="streak-heading"><span>🔥</span><div><h3>${labels.title}</h3><small>${s.days?`${s.current} ${ar?'يوم':fr?'jour(s)':'day(s)'}`:labels.empty}</small></div></div><div class="streak-stats"><div><b>${s.current}</b><small>${labels.current}</small></div><div><b>${s.longest}</b><small>${labels.best}</small></div><div><b>${s.days}</b><small>${labels.active}</small></div></div></section>`;
}
function progressPage(){const s=progressStats(),recent=s.items.slice(-8).reverse();return `${sectionHead(t('progress'),t('progressHint'))}${adaptivePlanPanel()}${studyStreakPanel(s.items)}<div class="stats-grid"><div class="stat-card"><div class="stat-icon">✓</div><div><b>${s.total}</b><small>${t('completed')}</small></div></div><div class="stat-card"><div class="stat-icon">🎯</div><div><b>${s.accuracy}%</b><small>${t('accuracy')}</small></div></div><div class="stat-card"><div class="stat-icon">▣</div><div><b>${s.tests}</b><small>${t('testsTaken')}</small></div></div><div class="stat-card"><div class="stat-icon">☀</div><div><b>${Math.min(s.today,3)}/3</b><small>${t('dailyGoal')}</small></div></div></div><div class="panel progress-panel"><h3>${t('dailyGoal')}</h3><p>${t('dailyGoalText')}</p><div class="goal-track"><span style="width:${Math.min(100,s.today/3*100)}%"></span></div><b>${Math.min(s.today,3)} / 3</b>${s.today>=3?`<p class="goal-success">${t('goalReached')}</p>`:''}</div><div class="panel progress-panel"><h3>${t('recentActivity')}</h3>${recent.length?`<div class="activity-list">${recent.map(x=>`<div class="activity-row"><span>${x.mode==='tests'?'▣':'✎'}</span><div><b>${x.subject}</b><small>${x.grade} · ${x.date}</small></div><strong>${x.correct}/${x.total}</strong></div>`).join('')}</div>`:`<div class="empty-note">${t('noActivity')}</div>`}<button class="secondary-btn" onclick="clearProgress()">${t('resetProgress')}</button></div>${localBackupPanel()}`}
