function plannerSubjectLabel(subject){if(lang==='ar')return subject;const map={ 'اللغة العربية':lang==='fr'?'Arabe':'Arabic','الرياضيات':lang==='fr'?'Mathématiques':'Mathematics','اللغة الفرنسية':lang==='fr'?'Français':'French','اللغة الإنجليزية':lang==='fr'?'Anglais':'English','العلوم الطبيعية':lang==='fr'?'Sciences naturelles':'Natural sciences','العلوم الفيزيائية والتكنولوجيا':lang==='fr'?'Sciences physiques et technologie':'Physical sciences and technology','العلوم الفيزيائية':lang==='fr'?'Sciences physiques':'Physics','التاريخ والجغرافيا':lang==='fr'?'Histoire-géographie':'History and geography','الفلسفة':lang==='fr'?'Philosophie':'Philosophy'};return map[subject]||subject}
