function buildRevisionPlan(track){const target=track==='BEM'?'middle':'secondary';const allowed=target==='middle'?['اللغة العربية','الرياضيات','اللغة الفرنسية','اللغة الإنجليزية','العلوم الطبيعية','العلوم الفيزيائية والتكنولوجيا','التاريخ والجغرافيا']:['اللغة العربية','الرياضيات','اللغة الفرنسية','اللغة الإنجليزية','العلوم الطبيعية','العلوم الفيزيائية','الفلسفة'];const records=getProgress().filter(x=>x.grade&&((target==='middle'&&x.grade.includes('متوسط'))||(target==='secondary'&&x.grade.includes('ثانوي'))));const performance=allowed.map(subject=>{const rows=records.filter(x=>x.subject===subject);const total=rows.reduce((n,x)=>n+(x.total||0),0),correct=rows.reduce((n,x)=>n+(x.correct||0),0);return {subject,rate:total?correct/total:0.5,seen:total}}).sort((a,b)=>a.rate-b.rate);const pool=performance.slice(0,4).map(x=>x.subject);const tasks={ar:['مراجعة المفاهيم الأساسية وحل 5 أسئلة','تدريب تطبيقي وتصحيح الأخطاء','تلخيص الدرس واسترجاع القواعد','اختبار قصير دون الرجوع إلى الملخص'],fr:['Revoir les notions clés et résoudre 5 questions','Faire des exercices et corriger les erreurs','Résumer la leçon et mémoriser les règles','Faire un mini-test sans consulter le résumé'],en:['Review key concepts and solve 5 questions','Practice and correct mistakes','Summarize the lesson and recall key rules','Take a short quiz without notes']}[lang];const days=Array.from({length:7},(_,i)=>({subject:pool[i%pool.length],task:tasks[i%tasks.length],done:false}));localStorage.setItem('smSchoolRevisionPlan',JSON.stringify({track,createdAt:new Date().toISOString(),days}));render()}
function toggleRevisionDay(index,done){const plan=loadRevisionPlan();if(!plan?.days?.[index])return;plan.days[index].done=done;localStorage.setItem('smSchoolRevisionPlan',JSON.stringify(plan));render()}
function lessonLibraryPage(){const group=level,items=starterLessons.filter(x=>x.g===group&&(!x.gr||x.gr===grade)).sort((a,b)=>(b.gr===grade)-(a.gr===grade));const labels={ar:{title:'مكتبة الدروس التمهيدية',desc:'دروس قصيرة وأهداف وأنشطة تطبيقية للانطلاق. محتوى تكميلي من إعداد المنصة وليس بديلاً عن الكتاب المدرسي.',open:'افتح الدرس',tag:'درس تكميلي',empty:'ستضاف دروس أخرى بعد المراجعة.'},fr:{title:'Bibliothèque de leçons de démarrage',desc:'Courtes leçons, objectifs et activités. Contenu complémentaire créé par la plateforme, non substitutif au manuel.',open:'Ouvrir',tag:'Leçon complémentaire',empty:'D’autres leçons seront ajoutées après révision.'},en:{title:'Starter lesson library',desc:'Short lessons, objectives and activities. Supplemental platform content, not a replacement for official textbooks.',open:'Open lesson',tag:'Supplemental lesson',empty:'More lessons will be added after review.'}}[lang];return `<div class="notice">${labels.desc}</div><div class="lesson-grid">${items.map((x,i)=>`<article class="panel lesson-card"><span class="pill">${labels.tag}</span><small>${x.s}</small><h3>${(x.title[lang]||x.title.ar)}</h3><p>${(x.goal[lang]||x.goal.ar)}</p><button class="primary-btn" onclick="openStarterLesson(${starterLessons.indexOf(x)})">${labels.open} ↗</button></article>`).join('')||`<div class="empty-note">${labels.empty}</div>`}</div>`}
function openStarterLesson(index){const x=starterLessons[index];if(!x)return;const labels={ar:{goal:'هدف التعلم',activity:'تحقق من فهمك',answer:'الإجابة المقترحة',complete:'أنهيت الدرس',back:'العودة للدروس'},fr:{goal:'Objectif',activity:'Vérifiez votre compréhension',answer:'Réponse proposée',complete:'Leçon terminée',back:'Retour aux leçons'},en:{goal:'Learning goal',activity:'Check your understanding',answer:'Suggested answer',complete:'Mark lesson complete',back:'Back to lessons'}}[lang];$('#pageContent').innerHTML=`${sectionHead((x.title[lang]||x.title.ar),grade+' · '+x.s)}<article class="panel lesson-detail"><span class="pill">${lang==='ar'?'محتوى تكميلي':lang==='fr'?'Contenu complémentaire':'Supplemental content'}</span><h2>${(x.title[lang]||x.title.ar)}</h2><h4>${labels.goal}</h4><p>${(x.goal[lang]||x.goal.ar)}</p><div class="lesson-explanation">${(x.body[lang]||x.body.ar)}</div><h4>${labels.activity}</h4><p>${(x.task[lang]||x.task.ar)}</p><details class="lesson-answer"><summary>${labels.answer}</summary><p>${(x.answer[lang]||x.answer.ar)}</p></details><button class="primary-btn" onclick="completeStarterLesson(${index})">✓ ${labels.complete}</button><button class="text-btn" onclick="render()">${labels.back}</button></article>`}
function completeStarterLesson(index){const x=starterLessons[index];if(!x)return;recordProgress('lessons',x.s,1,1);toast(lang==='ar'?'تم تسجيل إكمال الدرس':lang==='fr'?'Leçon enregistrée':'Lesson completion saved');go('progress')}
function learnerManager(){const learners=ensureDefaultLearner(),active=activeLearner(),ar=lang==='ar',fr=lang==='fr';const title=ar?'ملفات الأبناء':fr?'Profils des enfants':'Learner profiles';const desc=ar?'أنشئ ملفاً مستقلاً لكل طفل حتى لا تختلط نتائجهم. تحفظ الملفات والنتائج محلياً على هذا الجهاز.':fr?'Un profil séparé pour chaque enfant. Les données restent sur cet appareil.':'Keep each child’s learning history separate. Profiles and progress stay on this device.';return `<section class="panel learner-manager"><div class="learner-manager-head"><div><h3>👨‍👩‍👧 ${title}</h3><p>${desc}</p></div><span class="pill">${learners.length}/20</span></div><label class="learner-select-label">${ar?'الملف النشط':fr?'Profil actif':'Active profile'}<select onchange="selectLearner(this.value)">${learners.map(x=>`<option value="${x.id}" ${x.id===active.id?'selected':''}>${escapeReviewText(x.name)} · ${escapeReviewText(x.grade)}</option>`).join('')}</select></label><div class="learner-list">${learners.map(x=>`<div class="learner-row ${x.id===active.id?'active':''}"><div class="learner-avatar">${escapeReviewText((x.name||'?').slice(0,1))}</div><div class="learner-meta"><b>${escapeReviewText(x.name)}</b><small>${escapeReviewText(x.grade)} · ${x.id===active.id?(ar?'نشط':fr?'Actif':'Active'):(ar?'ملف محلي':fr?'Profil local':'Local profile')}</small></div>${learners.length>1?`<button class="text-btn learner-delete" onclick="deleteLearner('${x.id}')" aria-label="${ar?'حذف الملف':'Delete profile'}">×</button>`:''}</div>`).join('')}</div><div class="learner-add-row"><input id="newLearnerName" maxlength="50" placeholder="${ar?'اسم الطفل الجديد':fr?'Nom du nouvel enfant':'New learner name'}"><button class="primary-btn" onclick="addLearner()">＋ ${ar?'إضافة ملف':fr?'Ajouter':'Add profile'}</button></div></section>`}
function parentWeeklySummary(items,now=new Date()){
 const end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()));
 const start=new Date(end);start.setUTCDate(start.getUTCDate()-6);
 const from=start.toISOString().slice(0,10),to=end.toISOString().slice(0,10);
 const recent=(Array.isArray(items)?items:[]).filter(x=>x&&typeof x.date==='string'&&x.date>=from&&x.date<=to);
 const bySubject={};let correct=0,total=0;
 recent.forEach(x=>{const subject=String(x.subject||'—');const row=bySubject[subject]||(bySubject[subject]={subject,activities:0,correct:0,total:0});row.activities++;row.correct+=Number(x.correct)||0;row.total+=Number(x.total)||0;correct+=Number(x.correct)||0;total+=Number(x.total)||0});
 const subjects=Object.values(bySubject).map(x=>({...x,accuracy:x.total?Math.round(x.correct/x.total*100):null})).sort((a,b)=>(a.accuracy??101)-(b.accuracy??101)||b.activities-a.activities);
 const needsSupport=subjects.filter(x=>x.total>=5&&x.accuracy<60);
 const strong=subjects.filter(x=>x.total>=5&&x.accuracy>=85);
 return {from,to,activities:recent.length,correct,total,accuracy:total?Math.round(correct/total*100):0,subjects,needsSupport,strong};
}
function parentWeeklyPlan(weekly){
 const w=weekly||{},ar=lang==='ar',fr=lang==='fr';
 const focus=(w.needsSupport||[]).map(x=>x.subject);
 const available=(w.subjects||[]).map(x=>x.subject);
 const subjects=focus.length?focus:(available.length?available:['']);
 const stages=ar
  ?['درس قصير وفهم الفكرة الأساسية','حل 5 تمارين متدرجة','تصحيح الأخطاء وشرح سببها','استرجاع القواعد دون النظر إلى الدرس','اختبار قصير من 5 أسئلة','تطبيق أو وضعية إدماجية','مراجعة خفيفة وتقييم التقدم']
  :fr
   ?['Leçon courte et compréhension','Résoudre 5 exercices progressifs','Corriger et expliquer les erreurs','Rappeler les règles sans le cours','Petit test de 5 questions','Application ou situation d’intégration','Révision légère et bilan']
   :['Short lesson and core concept','Solve 5 graded exercises','Correct mistakes and explain why','Recall rules without notes','Short 5-question quiz','Applied or integrative task','Light review and progress check'];
 return stages.map((task,i)=>({day:i+1,subject:subjects[i%subjects.length],task})).map(x=>({...x,task:!x.subject?(ar?'اختر مادة وابدأ بمراجعة قصيرة':fr?'Choisissez une matière et révisez brièvement':'Choose a subject and begin with a short review'):x.task}));
}
function parentWeeklyPanel(items){
 const w=parentWeeklySummary(items),ar=lang==='ar',fr=lang==='fr';
 const title=ar?'ملخص الأسبوع الأخير':fr?'Bilan des 7 derniers jours':'Last 7 days';
 const recommendation= w.activities===0
  ?(ar?'لم تُسجّل أنشطة خلال الأيام السبعة الأخيرة. ابدأ بحصة قصيرة ثم سجّل النتائج.':fr?'Aucune activité enregistrée ces sept derniers jours. Commencez par une courte séance.':'No activity recorded in the last seven days. Start with a short session and record the result.')
  :w.needsSupport.length
   ?(ar?'يُنصح بمراجعة المواد الآتية عبر درس قصير ثم تمارين متدرجة: ':fr?'Révisez ces matières avec une courte leçon puis des exercices progressifs : ':'Prioritise these subjects with a short lesson followed by graduated practice: ')+w.needsSupport.map(x=>escapeReviewText(x.subject)).join('، ')
   :w.strong.length
    ?(ar?'الأداء جيد في المواد التي تتوفر لها خمس إجابات على الأقل. واصل التدريب مع تنويع الأسئلة.':fr?'Les résultats sont bons dans les matières avec au moins cinq réponses. Continuez avec des questions variées.':'Performance is strong in subjects with at least five answers. Keep practising with varied questions.')
    :(ar?'تحتاج البيانات إلى مزيد من الأنشطة قبل تحديد نقاط القوة والمواد التي تحتاج إلى دعم.':fr?'Il faut davantage d’activités pour identifier les points forts et les matières à renforcer.':'More activity is needed before identifying strengths and subjects needing support.');
 const rows=w.subjects.map(x=>`<div class="activity-row"><div><b>${escapeReviewText(x.subject)}</b><small>${x.activities} ${ar?'نشاط':fr?'activités':'activities'} · ${x.total} ${ar?'إجابة':fr?'réponses':'answers'}</small></div><strong>${x.accuracy===null?'—':x.accuracy+'%'}</strong></div>`).join('');
 return `<section class="panel parent-weekly"><h3>📅 ${title}</h3><p>${w.from} — ${w.to}</p><div class="stats-grid"><div class="stat-card"><b>${w.activities}</b><small>${ar?'الأنشطة':fr?'Activités':'Activities'}</small></div><div class="stat-card"><b>${w.accuracy}%</b><small>${ar?'الدقة الإجمالية':fr?'Précision globale':'Overall accuracy'}</small></div><div class="stat-card"><b>${w.needsSupport.length}</b><small>${ar?'مواد تحتاج دعماً':fr?'À renforcer':'Need support'}</small></div></div><h4>${ar?'حسب المادة':fr?'Par matière':'By subject'}</h4>${rows||`<div class="empty-note">${ar?'لا توجد نتائج مسجلة في هذه الفترة.':fr?'Aucun résultat sur cette période.':'No results in this period.'}</div>`}<h4>${ar?'خطة منزلية مقترحة للأيام السبعة القادمة':fr?'Plan familial proposé pour les 7 prochains jours':'Suggested 7-day home study plan'}</h4><ol class="parent-weekly-plan">${parentWeeklyPlan(w).map(x=>`<li><b>${ar?'اليوم':fr?'Jour':'Day'} ${x.day}</b> · ${escapeReviewText(x.subject|| (ar?'مادة يختارها الولي':fr?'matière au choix':'chosen subject'))}<small>${x.task}</small></li>`).join('')}</ol><div class="notice">${ar?'توصية للأسبوع القادم: ':fr?'Conseil pour la semaine prochaine : ':'Next-week recommendation: '}${recommendation}</div><small>${ar?'التصنيف إرشادي ويُحسب من النتائج المسجلة محلياً فقط؛ لا يُعد تقييماً رسمياً.':fr?'Indication calculée uniquement à partir des résultats locaux ; ce n’est pas une évaluation officielle.':'Guidance based only on locally recorded results; it is not an official assessment.'}</small></section>`;
}
function parentDashboard(){if(typeof parentAuthUser==='undefined'||!parentAuthUser)return '';const s=progressStats(),items=s.items,bySubject={};items.forEach(x=>{const k=x.subject||'—';if(!bySubject[k])bySubject[k]={correct:0,total:0,activities:0};bySubject[k].correct+=x.correct||0;bySubject[k].total+=x.total||0;bySubject[k].activities++});const rows=Object.entries(bySubject).sort((a,b)=>a[1].activities-b[1].activities).map(([name,v])=>`<div class="activity-row"><div><b>${name}</b><small>${v.activities} ${lang==='ar'?'نشاط':lang==='fr'?'activités':'activities'}</small></div><strong>${v.total?Math.round(v.correct/v.total*100):0}%</strong></div>`).join('');const recent=items.slice(-5).reverse();return `${typeof familyDashboardPanel==='function'?familyDashboardPanel():''}${learnerManager()}${parentWeeklyPanel(items)}<div class="panel parent-dashboard"><h3>${lang==='ar'?'ملخص متابعة التلميذ':lang==='fr'?'Résumé de suivi de l’élève':'Student progress snapshot'}</h3><p>${lang==='ar'?'هذه البيانات محفوظة على هذا الجهاز فقط. لا تُرسل تلقائياً إلى أي جهة.':lang==='fr'?'Ces données restent sur cet appareil et ne sont pas envoyées automatiquement.':'This information stays on this device and is not automatically shared.'}</p><div class="stats-grid"><div class="stat-card"><b>${s.total}</b><small>${lang==='ar'?'الأنشطة':lang==='fr'?'Activités':'Activities'}</small></div><div class="stat-card"><b>${s.accuracy}%</b><small>${lang==='ar'?'الدقة':lang==='fr'?'Précision':'Accuracy'}</small></div><div class="stat-card"><b>${s.tests}</b><small>${lang==='ar'?'الاختبارات':lang==='fr'?'Tests':'Tests'}</small></div><div class="stat-card"><b>${Math.min(s.today,3)}/3</b><small>${lang==='ar'?'هدف اليوم':lang==='fr'?'Objectif du jour':'Daily goal'}</small></div></div><h4>${lang==='ar'?'الأداء حسب المادة':lang==='fr'?'Résultats par matière':'Performance by subject'}</h4>${rows||`<div class="empty-note">${t('noActivity')}</div>`}<h4>${lang==='ar'?'آخر الأنشطة':lang==='fr'?'Activités récentes':'Recent activity'}</h4>${recent.length?recent.map(x=>`<div class="activity-row"><div><b>${x.subject}</b><small>${x.grade} · ${x.date}</small></div><strong>${x.correct}/${x.total}</strong></div>`).join(''):`<div class="empty-note">${t('noActivity')}</div>`}<button class="primary-btn" onclick="downloadParentReport()">${lang==='ar'?'تصدير تقرير المتابعة':lang==='fr'?'Exporter le rapport':'Export progress report'} ↓</button></div>`}
function downloadParentReport(){const s=progressStats();const lines=[['learner','date','grade','subject','type','correct','total'],...s.items.map(x=>[x.learnerName||s.learner.name,x.date,x.grade,x.subject,x.mode,x.correct,x.total])];const csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='SM-SCHOOL-AI-progress-report.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function contentPage(p){if(p==='studycenter')return '<div id="studyCenterMount"></div>';let [title,hint,ic]=pageInfo[p];let extra='';if(p==='translate')return translatePage();if(p==='certificates')extra=examSimulatorPage()+revisionPlannerPage();else if(p==='library')extra=lessonLibraryPage();else if(p==='exercises')return exerciseBankHomePage();else if(p==='tests')return testBankHomePage();else if(p==='homeschool')return typeof homeSchoolPage==='function'?homeSchoolPage():'';else if(p==='parents')extra=(typeof parentAccountPanel==='function'?parentAccountPanel():'')+parentDashboard()+(typeof parentAuthUser!=='undefined'&&parentAuthUser&&typeof familyPlannerPanel==='function'?familyPlannerPanel():'')+`<div class="panel"><h3>فضاء الأولياء الرسمي</h3><p style="font-size:12px;color:var(--muted)">${hint}</p><a class="primary-btn" style="display:inline-block;text-decoration:none" href="https://awlyaa.education.dz/" target="_blank" rel="noopener">${t('openOfficial')} ↗</a></div>`;else if(p==='computing')extra=aiLearnPage();else if(p==='videos')extra=`<div class="panel"><p style="font-size:12px;color:var(--muted)">${hint}</p><div class="toolbar"><input id="videoSearch" placeholder="${t('search')}"><button class="primary-btn" onclick="searchYouTube()">YouTube ↗</button></div></div>`;else {const gradeSubjects=subjectsForCurrentGrade();extra=`${curriculumNotice()}${secondaryPathwayMatrixPanel()}<div class="notice">${t('coming')}</div><div class="toolbar"><input id="filterInput" placeholder="${t('search')}" oninput="filterSubjects()"><select id="subjectFilter"><option>${t('all')}</option>${gradeSubjects.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="subject-grid" id="subjectGrid">${subjectCards(gradeSubjects)}</div>`;}return `${sectionHead(t(title),grade)}<div class="panel" style="margin-bottom:14px"><div style="font-size:26px;margin-bottom:7px">${ic}</div><p style="font-size:12px;color:var(--muted);margin:0">${t(hint)}</p></div>${extra}`}
function subjectCards(list){return list.map((s,i)=>`<div class="subject-card" onclick="openSubject('${s.replaceAll("'","\\'")}','${page}')"><div class="subject-emoji">${icons[i%icons.length]}</div><strong>${s}</strong><small>${grade}</small><span class="pill">${page==='library'?'PDF':page==='exercises'?'تمارين':'اختبارات'}</span></div>`).join('')}
function filterSubjects(){let q=$('#filterInput').value.toLowerCase();let list=subjectsForCurrentGrade().filter(s=>s.toLowerCase().includes(q));$('#subjectGrid').innerHTML=list.length?subjectCards(list):`<div class="empty-note">${t('noResults')}</div>`}
function openSubject(s,p){if(p==='exercises'){renderExerciseBank(s);return}if(p==='tests'){const pack=subjectPractice[s]?.[level]||(/رياضيات|Mathématiques|Mathematics/i.test(s)?demoBank[level]:null);if(pack){renderMathPractice(p,s);return}$('#pageContent').innerHTML=`${sectionHead(s,grade)}<div class="panel"><div class="notice">${t('practiceDemo')}</div><p>${lang==='ar'?'نعمل على إعداد تمارين لهذه المادة ومطابقتها مع المستوى الدراسي.':'Practice activities for this subject are being prepared and reviewed for this grade.'}</p><button class="secondary-btn" onclick="render()">${t('backSubjects')}</button></div>`;return}const labels={ar:{books:'الكتاب والموارد',exercises:'التمارين والتدريب',tests:'التقييم والاختبارات',unit:'محتوى الفصل',pending:'لم تُعتمد الدروس بعد'},fr:{books:'Manuel et ressources',exercises:'Exercices et entraînement',tests:'Évaluation et tests',unit:'Contenu du trimestre',pending:'Leçons non encore validées'},en:{books:'Books and resources',exercises:'Practice and exercises',tests:'Assessment and tests',unit:'Term content',pending:'Lessons are not yet verified'}}[lang];const terms=TERM_LABELS[lang]||TERM_LABELS.en;const termCards=terms.map((name,i)=>`<article class="term-card"><div class="term-card-head"><b>${name}</b><span class="pill">${labels.pending}</span></div><p>${labels.unit} · ${s}</p><small>${CONTENT_STATUS[lang]||CONTENT_STATUS.en}</small></article>`).join('');const source=p==='library'?`<p><a href="https://www.onps.dz/" target="_blank" rel="noopener">${lang==='ar'?'الديوان الوطني للمطبوعات المدرسية ONPS':lang==='fr'?'Office national des publications scolaires (ONPS)':'National Office of School Publications (ONPS)'} ↗</a></p>`:'';$('#pageContent').innerHTML=`${sectionHead(s,grade)}<div class="panel learning-outline"><div class="learning-outline-meta"><span>${ACADEMIC_YEAR}</span><span>${grade}</span><span>${s}</span></div><h3>${p==='library'?labels.books:p==='exercises'?labels.exercises:labels.tests}</h3>${source}<div class="notice">${CONTENT_STATUS[lang]||CONTENT_STATUS.en}. ${SOURCE_LABEL[lang]||SOURCE_LABEL.en}: <a href="https://www.education.gov.dz/" target="_blank" rel="noopener">education.gov.dz</a></div><div class="term-grid">${termCards}</div><p class="content-integrity-note">${lang==='ar'?'لن ننسب أي درس أو تمرين إلى البرنامج الرسمي قبل مطابقة عنوانه وكفاءته مع الوثيقة الوزارية المناسبة.':'No lesson or exercise is labelled official until its title and competency are checked against the corresponding ministry document.'}</p><button class="primary-btn" style="margin-top:15px" onclick="render()">${t('all')} ←</button></div>`}
function exerciseCoverageSummary(){
 const gradeNames=levels.primary.concat(levels.middle,levels.secondary);
 const stageGroups=[{key:'primary',grades:levels.primary},{key:'middle',grades:levels.middle},{key:'secondary',grades:levels.secondary}];
 const pairs=gradeNames.map(g=>{const rows=exerciseBankRecords.filter(x=>x.grade===g);return {grade:g,subjects:[...new Set(rows.map(x=>x.subject))].length,count:rows.length,min:rows.length?Math.min(...[...new Set(rows.map(x=>x.subject))].map(s=>rows.filter(x=>x.subject===s).length)):0}});
 const ar=lang==='ar',fr=lang==='fr';
 const labels=ar?{title:'خريطة تغطية المواد',desc:'ملخص فعلي لما هو موجود في بنك التمارين مقارنة بفهرس مواد المنصة، وليس إثباتاً للمطابقة الوزارية.',grades:'سنوات',pairs:'مجموعات سنة/مادة',exercises:'تمارين',covered:'مجموعات بها تمارين',minimum:'الحد الأدنى لكل مادة',official:'المطابقة الوزارية التفصيلية: لم يتم التحقق منها بعد'}:fr?{title:'Carte de couverture des matières',desc:'Résumé réel de la banque par rapport à l’index des matières de la plateforme, sans prétendre à une validation ministérielle.',grades:'Niveaux',pairs:'Couples niveau/matière',exercises:'Exercices',covered:'Couples avec exercices',minimum:'Minimum par matière',official:'Alignement ministériel détaillé : non vérifié'}:{title:'Subject coverage map',desc:'Actual exercise-bank coverage against the platform subject index; this is not proof of Ministry alignment.',grades:'Grades',pairs:'Grade/subject pairs',exercises:'Exercises',covered:'Pairs with exercises',minimum:'Minimum per subject',official:'Detailed Ministry alignment: not yet verified'};
 const totalPairs=pairs.reduce((n,x)=>n+x.subjects,0),covered=pairs.reduce((n,x)=>n+(x.subjects>0?x.subjects:0),0);
 const stages=stageGroups.map(st=>{const subset=pairs.filter(x=>st.grades.includes(x.grade));const label=ar?({primary:'ابتدائي',middle:'متوسط',secondary:'ثانوي'}[st.key]):fr?({primary:'Primaire',middle:'Moyen',secondary:'Secondaire'}[st.key]):({primary:'Primary',middle:'Middle',secondary:'Secondary'}[st.key]);return `<div class="coverage-stage"><b>${label}</b><span>${subset.length} ${labels.grades}</span><strong>${subset.reduce((n,x)=>n+x.count,0)}</strong><small>${labels.exercises}</small></div>`}).join('');
 const gradeRows=pairs.map(x=>`<tr><td>${x.grade}</td><td>${x.subjects}</td><td>${x.count}</td><td>${x.min||0}</td></tr>`).join('');
 return `<section class="panel coverage-panel"><h3>${labels.title}</h3><p>${labels.desc}</p><div class="coverage-stages">${stages}</div><div class="coverage-kpis"><div><b>${exerciseBankRecords.length}</b><small>${labels.exercises}</small></div><div><b>${totalPairs}</b><small>${labels.pairs}</small></div><div><b>${covered}/${totalPairs}</b><small>${labels.covered}</small></div><div><b>8</b><small>${labels.minimum}</small></div></div><details class="coverage-details"><summary>${ar?'تفاصيل التغطية حسب السنة':fr?'Détail par niveau':'Coverage details by grade'}</summary><div class="coverage-table-wrap"><table class="coverage-table"><thead><tr><th>${ar?'السنة':fr?'Niveau':'Grade'}</th><th>${ar?'المواد':fr?'Matières':'Subjects'}</th><th>${labels.exercises}</th><th>${ar?'أقل عدد لمادة':fr?'Minimum':'Minimum'}</th></tr></thead><tbody>${gradeRows}</tbody></table></div></details><p class="notice">${labels.official}</p></section>`;
}
function exerciseBankHomePage(){
 const records=exerciseBankRecords.filter(x=>x.grade===grade),subjectsNow=[...new Set(records.map(x=>x.subject))];
 const ar=lang==='ar',fr=lang==='fr';
 const heading=ar?'بنك تمارين شامل لجميع المواد والأطوار':fr?'Banque d’exercices pour toutes les matières':'Exercise bank for all subjects and school levels';
 const intro=ar?'اختر السنة والمادة والفصل ومستوى الصعوبة. ستجد أسئلة مفاهيمية وتمارين تطبيقية ومسائل متعددة الخطوات مع حلول مشروحة.':fr?'Choisissez le niveau, la matière, le trimestre et la difficulté. Retrouvez des exercices d’application et des problèmes à étapes avec corrigés.':'Choose a grade, subject, term and difficulty. Practice concepts, applied exercises and multi-step problems with worked solutions.';
 const gradeLabel=ar?'السنة الدراسية':fr?'Année scolaire':'School grade';
 const countLabel=ar?'تمرين متاح':fr?'exercices disponibles':'exercises available';
 const subjectLabel=ar?'المواد المتاحة':fr?'Matières disponibles':'Available subjects';
 const count=records.length;
 return `${sectionHead(heading,grade)}<div class="panel exercise-bank-hero"><div class="learning-meta"><b>🏦 ${ar?'بنك التمارين':fr?'Banque d’exercices':'Exercise bank'}</b><span>${exerciseBankRecords.length} ${ar?'تمريناً':fr?'exercices':'exercises'} · 12 ${ar?'سنة':fr?'niveaux':'grades'}</span></div><p>${intro}</p><div class="toolbar"><label style="flex:1;min-width:190px">${gradeLabel}<select id="exerciseGradeSelect" onchange="chooseExerciseGrade(this.value)">${levels.primary.concat(levels.middle,levels.secondary).map(g=>`<option value="${g}" ${g===grade?'selected':''}>${g}</option>`).join('')}</select></label><div class="bank-count"><strong>${count}</strong><small>${countLabel}</small></div></div>${secondaryPathwayNotice()}${secondaryPathwayMatrixPanel()}<div class="notice">${ar?'المحتوى تدريبي من إعداد المنصة وليس مواضيع أو حلولاً وزارية رسمية. توجد تمارين لكل مادة مدرجة في فهرس السنوات الـ12، بثمانية تمارين على الأقل لكل مجموعة سنة/مادة؛ ولا يعني ذلك اعتماداً وزارياً للمحتوى.':fr?'Contenu créé par la plateforme, non officiel : au moins huit exercices par couple niveau/matière de l’index.':'Platform-created practice content, not official ministry papers or answer keys; at least eight exercises per indexed grade/subject pair.'}</div></div>${exerciseCoverageSummary()}<h3 class="bank-section-title">${subjectLabel} · ${subjectsNow.length}</h3><div class="subject-grid">${subjectsNow.map((sub,i)=>{const n=records.filter(x=>x.subject===sub).length;return `<div class="subject-card" onclick="renderExerciseBank('${sub.replaceAll("'","\\'")}')"><div class="subject-emoji">${icons[i%icons.length]}</div><strong>${sub}</strong><small>${grade}</small><span class="pill">${n} ${ar?'تمارين':fr?'exercices':'exercises'}</span></div>`}).join('')}</div>${!exerciseBankRecords.length?`<div class="notice">${ar?'جارٍ تحميل بنك التمارين...':fr?'Chargement de la banque…':'Loading exercise bank…'}</div>`:''}${window.SM_STUDY_DOWNLOAD?window.SM_STUDY_DOWNLOAD.panelHtml():''}`;
}
function chooseExerciseGrade(name){const group=levels.primary.includes(name)?'primary':levels.middle.includes(name)?'middle':'secondary';level=group;grade=name;localStorage.setItem('smSchoolLevel',group);localStorage.setItem('smSchoolGrade',name);updateActiveLearnerGrade(group,name);$('#levelSummary').textContent=name;renderExerciseBankHome();}
function renderExerciseBankHome(){exerciseBankSubject='';exerciseFilters={term:'all',difficulty:'all',cognitive:'all',topic:'all',search:''};$('#pageContent').innerHTML=exerciseBankHomePage();if(window.SM_STUDY_DOWNLOAD)window.SM_STUDY_DOWNLOAD.refreshPanel();}
function setExerciseFilter(key,value){exerciseFilters[key]=value;renderExerciseBank(exerciseBankSubject);}
function renderExerciseBank(subject){
 exerciseBankSubject=subject;
 const allRecords=exerciseBankRecords.filter(x=>x.grade===grade&&x.subject===subject);
 const topics=[...new Set(allRecords.map(x=>x.topic))];
 const records=allRecords.filter(x=>(exerciseFilters.term==='all'||String(x.term)===exerciseFilters.term)&&(exerciseFilters.difficulty==='all'||x.difficulty===exerciseFilters.difficulty)&&(exerciseFilters.cognitive==='all'||x.cognitive_process===exerciseFilters.cognitive)&&(exerciseFilters.topic==='all'||x.topic===exerciseFilters.topic)&&(!exerciseFilters.search||`${x.question} ${x.lesson} ${x.topic}`.toLowerCase().includes(exerciseFilters.search.toLowerCase())));
 const ar=lang==='ar',fr=lang==='fr';
 const mapped=records.map(x=>({q:x.question,choices:x.choices,a:x.answer_index,why:x.explanation,solution:x.solution,solution_steps:x.solution_steps,id:x.id,topic:x.topic,lesson:x.lesson,difficulty:x.difficulty,term:x.term,question_type:x.question_type,accepted_answers:x.accepted_answers,solution:x.solution,cognitive_process:x.cognitive_process,estimated_minutes:x.estimated_minutes}));
 const title=ar?'تمارين مادة':fr?'Exercices de':'Exercises ·';
 const termLabel=ar?'الفصل':fr?'Trimestre':'Term';
 const diffLabel=ar?'الصعوبة':fr?'Difficulté':'Difficulty';
 const topicLabel=ar?'الدرس / المحور':fr?'Leçon / thème':'Lesson / topic';
 const cognitiveLabel=ar?'المهارة الذهنية':fr?'Compétence cognitive':'Thinking skill';
 const cognitiveNames=ar?{recall:'تذكر',understand:'فهم',apply:'تطبيق',analyze:'تحليل',reason:'استدلال'}:fr?{recall:'Mémoriser',understand:'Comprendre',apply:'Appliquer',analyze:'Analyser',reason:'Raisonner'}:{recall:'Recall',understand:'Understand',apply:'Apply',analyze:'Analyze',reason:'Reason'};
 const allLabel=ar?'الكل':fr?'Tout':'All';
 const diffNames=ar?['مبتدئ','متوسط','متقدم']:fr?['Débutant','Intermédiaire','Avancé']:['Beginner','Intermediate','Advanced'];
 $('#pageContent').innerHTML=`${sectionHead(`${title} ${subject}`,grade)}<div class="notice">${ar?'اختر الإجابة ثم تحقق منها. استخدم «عرض الحل» لرؤية خطوات الحل، خاصة في المسائل التطبيقية.':fr?'Répondez puis vérifiez. Affichez la correction détaillée pour voir les étapes.':'Answer first, then check. Reveal the worked solution to see each reasoning step.'}</div><div class="panel exercise-filters"><label>${termLabel}<select onchange="setExerciseFilter('term',this.value)"><option value="all">${allLabel}</option><option value="1" ${exerciseFilters.term==='1'?'selected':''}>${ar?'الأول':fr?'1er':'First'}</option><option value="2" ${exerciseFilters.term==='2'?'selected':''}>${ar?'الثاني':fr?'2e':'Second'}</option><option value="3" ${exerciseFilters.term==='3'?'selected':''}>${ar?'الثالث':fr?'3e':'Third'}</option></select></label><label>${diffLabel}<select onchange="setExerciseFilter('difficulty',this.value)"><option value="all">${allLabel}</option>${['مبتدئ','متوسط','متقدم'].map((v,i)=>`<option value="${v}" ${exerciseFilters.difficulty===v?'selected':''}>${diffNames[i]}</option>`).join('')}</select></label><label>${cognitiveLabel}<select onchange="setExerciseFilter('cognitive',this.value)"><option value="all">${allLabel}</option>${['recall','understand','apply','analyze','reason'].map(v=>`<option value="${v}" ${exerciseFilters.cognitive===v?'selected':''}>${cognitiveNames[v]}</option>`).join('')}</select></label><label>${topicLabel}<select onchange="setExerciseFilter('topic',this.value)"><option value="all">${allLabel}</option>${topics.map(v=>`<option value="${v}" ${exerciseFilters.topic===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="filter-search"><span>${ar?'بحث':fr?'Recherche':'Search'}</span><input value="${exerciseFilters.search.replaceAll('"','&quot;')}" placeholder="${ar?'ابحث في نص التمرين أو الدرس':fr?'Rechercher un exercice':'Search exercises'}" oninput="setExerciseFilter('search',this.value)"></label></div><div class="panel learning-panel"><div class="learning-meta"><b>${subject}</b><span>${mapped.length} / ${allRecords.length} ${ar?'تمارين':fr?'exercices':'exercises'}</span></div><div class="exercise-session-actions"><button class="secondary-btn" onclick="SM_STUDY_DOWNLOAD.exportCurrent('exercise')">📥 ${ar?'إنشاء ملف التمارين مع التصحيح':fr?'Créer le fichier avec corrigé':'Create exercises + answers file'}</button><button class="primary-btn" onclick="startExerciseSession('random')">${ar?'جلسة عشوائية (10)':fr?'Session aléatoire (10)':'Random practice (10)'}</button><button class="secondary-btn" onclick="startExerciseSession('mistakes')">${ar?'مراجعة أخطائي':fr?'Réviser mes erreurs':'Review my mistakes'}</button></div>${mapped.map((q,i)=>`<article class="question-card"><div class="learning-meta"><small>${ar?'تمرين':fr?'Exercice':'Exercise'} ${i+1} · ${q.difficulty} · ${termLabel} ${q.term}</small><small>${q.topic} · ${q.lesson} · ${cognitiveNames[q.cognitive_process]||''} · ${q.estimated_minutes||1} ${ar?'د':fr?'min':'min'}</small></div>${q.question_type==='multi_step'?`<span class="pill applied-pill">${ar?'مسألة تطبيقية متعددة الخطوات':fr?'Problème à étapes':'Multi-step applied problem'}</span>`:''}<h4>${i+1}. ${q.q}</h4>${q.question_type==='numeric'?`<label class="typed-answer"><span>${ar?'اكتب إجابتك':fr?'Votre réponse':'Your answer'}</span><input type="text" inputmode="decimal" autocomplete="off" name="q${i}" placeholder="${ar?'أدخل الإجابة هنا':fr?'Saisir la réponse':'Enter your answer'}"></label>`:`<div class="answer-options">${q.choices.map((c,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${c}</label>`).join('')}</div>`}<div class="question-feedback" id="feedback${i}" aria-live="polite"></div><button class="secondary-btn" onclick="checkOne(${i})">${t('checkAnswer')}</button><button class="text-btn" onclick="showSolution(${i})">${t('showSolution')}</button></article>`).join('')||`<div class="empty-note">${ar?'لا توجد تمارين تطابق عوامل التصفية. جرّب اختيار «الكل».':fr?'Aucun exercice ne correspond aux filtres.':'No exercises match these filters. Try selecting All.'}</div>`}<button class="text-btn" onclick="renderExerciseBankHome()">${t('backSubjects')}</button></div>`;
 window.currentPractice={items:mapped,mode:'exercises',subject,answered:{},results:{},grade};
}
function exerciseMistakeKey(){return `smSchoolExerciseMistakes:${grade}:${exerciseBankSubject}`}
function getExerciseMistakes(){try{return JSON.parse(localStorage.getItem(exerciseMistakeKey())||'[]')}catch{return []}}
function startExerciseSession(mode='random'){
 const all=(window.currentPractice?.items||[]);const mistakes=getExerciseMistakes();
 let pool=mode==='mistakes'?all.filter(q=>mistakes.includes(q.id)):all;
 if(mode==='mistakes'&&!pool.length){toast(lang==='ar'?'لا توجد أخطاء محفوظة لهذه المادة.':'No saved mistakes for this subject yet.');return}
 if(!pool.length)return;
 const items=shuffleList(pool).slice(0,Math.min(10,pool.length));
 window.currentPractice={items,mode:'exercises',subject:exerciseBankSubject,answered:{},results:{},grade,session:true};
 const ar=lang==='ar',fr=lang==='fr';
 $('#pageContent').innerHTML=`${sectionHead(ar?'جلسة تدريب':fr?'Séance d’entraînement':'Practice session',grade)}<div class="notice">${mode==='mistakes'?(ar?'هذه مراجعة للأسئلة التي أخطأت فيها سابقاً.':fr?'Révision des questions précédemment incorrectes.':'Review questions you previously answered incorrectly.'):(ar?'تم اختيار الأسئلة عشوائياً من التمارين المطابقة لفلاترك.':fr?'Questions choisies aléatoirement selon vos filtres.':'Questions randomly selected from your filtered exercises.')}</div><div class="panel learning-panel"><div class="learning-meta"><b>${exerciseBankSubject}</b><span>${items.length} ${ar?'تمارين':fr?'exercices':'exercises'}</span></div><button class="secondary-btn" onclick="SM_STUDY_DOWNLOAD.exportCurrent('exercise')">📥 ${ar?'إنشاء ملف الجلسة مع التصحيح':'Create session + answers file'}</button>${items.map((q,i)=>`<article class="question-card"><div class="learning-meta"><small>${ar?'تمرين':fr?'Exercice':'Exercise'} ${i+1} · ${q.difficulty}</small><small>${q.topic} · ${q.lesson}</small></div><h4>${i+1}. ${q.q}</h4>${q.question_type==='numeric'?`<label class="typed-answer"><span>${ar?'اكتب إجابتك':fr?'Votre réponse':'Your answer'}</span><input type="text" inputmode="decimal" autocomplete="off" name="q${i}" placeholder="${ar?'أدخل الإجابة هنا':fr?'Saisir la réponse':'Enter your answer'}"></label>`:`<div class="answer-options">${q.choices.map((c,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${c}</label>`).join('')}</div>`}<div class="question-feedback" id="feedback${i}" aria-live="polite"></div><button class="secondary-btn" onclick="checkOne(${i})">${t('checkAnswer')}</button><button class="text-btn" onclick="showSolution(${i})">${t('showSolution')}</button></article>`).join('')}<button class="primary-btn" onclick="finishExerciseSession()">${ar?'إنهاء الجلسة وعرض النتيجة':fr?'Terminer et afficher le résultat':'Finish session and show result'}</button><div id="exerciseSessionResult" class="test-result" aria-live="polite"></div><button class="text-btn" onclick="renderExerciseBank(exerciseBankSubject)">${ar?'العودة إلى البنك':fr?'Retour à la banque':'Back to exercise bank'}</button></div>`;
}
function finishExerciseSession(){const p=window.currentPractice;if(!p?.session)return;const total=p.items.length,answered=Object.keys(p.results).length,correct=Object.values(p.results).filter(Boolean).length;const box=$('#exerciseSessionResult');if(!box)return;box.textContent=lang==='ar'?`النتيجة: ${correct}/${total}. أجبت عن ${answered} من ${total} تمارين.`:lang==='fr'?`Résultat : ${correct}/${total}. ${answered} réponses sur ${total}.`:`Score: ${correct}/${total}. Answered ${answered} of ${total}.`;box.classList.add('visible')}
