let pdfPreviewUrl=null;
function pdfReviewPanel(){
 const ar=lang==='ar',fr=lang==='fr';
 const L=ar?{title:'مراجعة ملفات PDF المستوردة',desc:'ارفع ملف PDF من جهازك. سيُحفظ في مساحة مراجعة خاصة ويُستخرج النص إن أمكن. لا تُنشر الأسئلة تلقائياً في بنك التمارين.',choose:'اختيار ملف PDF',upload:'رفع واستخراج النص',refresh:'تحديث القائمة',none:'لا توجد ملفات مستوردة بعد.',preview:'معاينة الملف',text:'النص المستخرج — قابل للتحرير',notes:'ملاحظات المراجع',status:'حالة المراجعة',pending:'بانتظار المراجعة',reviewed:'تمت المراجعة — غير معتمد للنشر',rights:'تم التحقق من الحقوق',save:'حفظ المراجعة',pages:'صفحات',size:'الحجم',extract:'حالة الاستخراج',duplicate:'هذا الملف مستورد مسبقاً.',saved:'تم حفظ المراجعة.',noApi:'تعذر الاتصال بالخادم. تأكد من تشغيل API وضبط عنوانه في config.js.',notice:'مهم: اختيار «تم التحقق من الحقوق» يسجل قرار المراجع فقط؛ لا ينشر المحتوى تلقائياً. يجب التأكد من إذن إعادة الاستخدام ومراجعة الإجابات بشرياً.',need:'اختر ملف PDF أولاً.'}:fr?{title:'Révision des PDF importés',desc:'Importez un PDF depuis votre appareil. Le fichier reste dans une zone privée et le texte est extrait si possible. Rien n’est publié automatiquement.',choose:'Choisir un PDF',upload:'Importer et extraire',refresh:'Actualiser',none:'Aucun document importé.',preview:'Aperçu du document',text:'Texte extrait — modifiable',notes:'Notes du réviseur',status:'État de révision',pending:'En attente de révision',reviewed:'Révisé — non approuvé',rights:'Droits vérifiés',save:'Enregistrer la révision',pages:'pages',size:'Taille',extract:'Extraction',duplicate:'Ce fichier est déjà importé.',saved:'Révision enregistrée.',noApi:'Connexion au serveur impossible. Vérifiez l’API et config.js.',notice:'Important : le statut des droits est une déclaration du réviseur, pas une publication. Vérifiez les autorisations et les réponses manuellement.',need:'Choisissez d’abord un PDF.'}:{title:'Imported PDF review workspace',desc:'Upload a PDF from your device. It is stored in a private review queue and text is extracted when possible. Nothing is published automatically.',choose:'Choose PDF file',upload:'Upload & extract',refresh:'Refresh list',none:'No imported documents yet.',preview:'Document preview',text:'Extracted text — editable',notes:'Reviewer notes',status:'Review status',pending:'Pending review',reviewed:'Reviewed — not approved',rights:'Rights checked',save:'Save review',pages:'pages',size:'Size',extract:'Extraction',duplicate:'This file was already imported.',saved:'Review saved.',noApi:'Could not reach the API. Check that the backend is running and configured in config.js.',notice:'Important: the rights status records a reviewer decision only; it does not publish content. Confirm reuse permission and manually review answers.',need:'Choose a PDF first.'};
 const rows=pdfReviewDocuments.map(d=>`<article class="pdf-review-row"><div><b>${escapeReviewText(d.filename)}</b><small>${d.page_count||0} ${L.pages} · ${Math.round((d.size_bytes||0)/1024)} KB · ${escapeReviewText(d.extraction_status||'')}</small><small>SHA-256: ${escapeReviewText((d.sha256||'').slice(0,20))}…</small></div><button class="secondary-btn" onclick="openPdfReview('${d.id}')">${L.preview}</button></article>`).join('');
 return `<section class="panel pdf-review-panel"><div class="learning-meta"><b>📄 ${L.title}</b><button class="text-btn" onclick="loadPdfReviewDocuments()">${L.refresh}</button></div><p>${L.desc}</p><div class="pdf-upload-controls"><input id="pdfReviewFile" type="file" accept="application/pdf,.pdf" aria-label="PDF file"><button class="primary-btn" onclick="uploadPdfReviewFile()">${L.upload}</button></div><div class="pdf-review-list">${rows||`<div class="empty-note">${L.none}</div>`}</div><div id="pdfReviewEditor" class="pdf-review-editor"></div><p class="notice">${L.notice}</p></section>`;
}
async function loadPdfReviewDocuments(){
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review`);if(!r.ok)throw new Error('API');const d=await r.json();pdfReviewDocuments=d.documents||[];if(page==='tests')renderTestBankHome()}catch(e){toast(lang==='ar'?'تعذر تحميل قائمة الملفات':lang==='fr'?'Impossible de charger la liste':'Could not load review list')}
}
async function uploadPdfReviewFile(){
 const input=$('#pdfReviewFile'),file=input?.files?.[0];if(!file){toast(lang==='ar'?'اختر ملف PDF أولاً':lang==='fr'?'Choisissez un PDF':'Choose a PDF first');return}if(file.size>50*1024*1024){toast('PDF limit: 50 MB');return}
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/upload?filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':'application/pdf'},body:file});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Upload failed');await loadPdfReviewDocuments();if(data.duplicate)toast(lang==='ar'?'الملف مستورد مسبقاً':lang==='fr'?'Document déjà importé':'File already imported');else{toast(lang==='ar'?'تم رفع الملف واستخراج النص':lang==='fr'?'PDF importé et texte extrait':'PDF uploaded and processed');openPdfReview(data.document.id)}}catch(e){toast((lang==='ar'?'فشل الرفع: ':lang==='fr'?'Échec de l’import : ':'Upload failed: ')+e.message)}
}
function openPdfReview(id){
 const d=pdfReviewDocuments.find(x=>x.id===id);if(!d)return;const ar=lang==='ar',fr=lang==='fr';const L=ar?{preview:'معاينة PDF',text:'النص المستخرج — يمكنك تصحيحه',notes:'ملاحظات المراجع',status:'حالة المراجعة',pending:'بانتظار المراجعة',reviewed:'تمت المراجعة دون اعتماد للنشر',rights:'تم التحقق من حقوق الاستخدام',save:'حفظ التعديلات'}:fr?{preview:'Aperçu PDF',text:'Texte extrait — modifiable',notes:'Notes du réviseur',status:'État',pending:'En attente',reviewed:'Révisé, non approuvé',rights:'Droits vérifiés',save:'Enregistrer'}:{preview:'PDF preview',text:'Extracted text — edit to correct OCR',notes:'Reviewer notes',status:'Review status',pending:'Pending review',reviewed:'Reviewed, not approved for publication',rights:'Reuse rights checked',save:'Save changes'};
 const editor=$('#pdfReviewEditor');if(pdfPreviewUrl)URL.revokeObjectURL(pdfPreviewUrl);pdfPreviewUrl=null;
 editor.innerHTML=`<div class="learning-meta"><b>${escapeReviewText(d.filename)}</b><span>${d.page_count||0} pages · ${escapeReviewText(d.extraction_status||'')}</span></div><label>${L.preview}<iframe class="pdf-review-frame" title="PDF preview" src="${apiBase()}/api/v1/archive/pdf-review/${id}/file"></iframe></label><label>${L.text}<textarea id="pdfReviewText" rows="12">${escapeReviewText(d.extracted_text||'')}</textarea></label><label>${L.notes}<textarea id="pdfReviewNotes" rows="3">${escapeReviewText(d.review_notes||'')}</textarea></label><label>${L.status}<select id="pdfReviewStatus"><option value="pending_review" ${d.status==='pending_review'?'selected':''}>${L.pending}</option><option value="reviewed_not_approved" ${d.status==='reviewed_not_approved'?'selected':''}>${L.reviewed}</option><option value="rights_cleared" ${d.status==='rights_cleared'?'selected':''}>${L.rights}</option></select></label><button class="primary-btn" onclick="savePdfReview('${id}')">${L.save}</button><div class="candidate-tools"><select id="pdfOcrLanguages" aria-label="OCR languages"><option value="ara+fra+eng">العربية + Français + English</option><option value="ara">العربية</option><option value="fra">Français</option><option value="eng">English</option><option value="ara+fra">العربية + Français</option><option value="ara+eng">العربية + English</option><option value="eng+fra">English + Français</option></select><button class="secondary-btn" onclick="runPdfOcr('${id}')">${ar?'تشغيل OCR للصفحات المصورة':fr?'Lancer OCR des pages scannées':'Run OCR on scanned pages'}</button><button class="secondary-btn" onclick="extractPdfCandidates('${id}')">${ar?'استخراج مرشحات الأسئلة':fr?'Détecter les questions':'Detect question candidates'}</button><button class="secondary-btn" onclick="extractCurriculumEvidenceCandidates('${id}')">${ar?'استخراج وحدات ودروس وكفاءات':fr?'Extraire unités, leçons et compétences':'Extract units, lessons & competencies'}</button><button class="secondary-btn" onclick="analyzePdfLayout('${id}')">${ar?'تحليل المعادلات والجداول والرسوم':fr?'Analyser formules, tableaux et figures':'Analyze equations, tables & figures'}</button><span>${ar?'استخراج آلي أولي يحتاج مراجعة بشرية':fr?'Segmentation indicative à vérifier':'Heuristic segmentation — human review required'}</span></div><div id="pdfLayoutMount"></div><div id="pdfCandidateMount"></div><div id="curriculumEvidenceCandidateMount"></div>`;loadPdfQuestionCandidates(id);loadPdfLayout(id);loadCurriculumEvidenceCandidates(id);
 editor.scrollIntoView({behavior:'smooth',block:'start'});
}
async function runPdfOcr(id){
 const languages=$('#pdfOcrLanguages')?.value||'ara+fra+eng';
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/ocr?languages=${encodeURIComponent(languages)}`,{method:'POST'});const data=await r.json();if(!r.ok)throw new Error(data.detail||'OCR failed');const i=pdfReviewDocuments.findIndex(x=>x.id===id);if(i>=0)pdfReviewDocuments[i]=data.document;openPdfReview(id);toast(lang==='ar'?`اكتمل OCR — ${data.text_characters} حرفاً`:lang==='fr'?`OCR terminé — ${data.text_characters} caractères`:`OCR completed — ${data.text_characters} characters`)}catch(e){toast((lang==='ar'?'تعذر تشغيل OCR: ':lang==='fr'?'Échec OCR : ':'OCR failed: ')+e.message)}
}
async function extractCurriculumEvidenceCandidates(id){
 const mount=$('#curriculumEvidenceCandidateMount');if(mount)mount.innerHTML='<p class="notice">Extracting page-anchored curriculum evidence…</p>';
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/extract-curriculum-candidates`,{method:'POST'});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Extraction failed');await loadCurriculumEvidenceCandidates(id);toast(lang==='ar'?`تم إنشاء ${data.created} مرشحاً للمراجعة`:lang==='fr'?`${data.created} propositions créées`:`${data.created} review candidates created`)}catch(e){if(mount)mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`;toast(e.message)}
}
async function loadCurriculumEvidenceCandidates(id){
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/curriculum-candidates`);if(r.ok)renderCurriculumEvidenceCandidates(await r.json())}catch(e){}
}
function renderCurriculumEvidenceCandidates(data){
 const mount=$('#curriculumEvidenceCandidateMount');if(!mount)return;const ar=lang==='ar',fr=lang==='fr';const title=ar?'مرشحات التدرجات — مراجعة بشرية':fr?'Propositions de progression — révision humaine':'Curriculum evidence candidates — human review';
 const rows=(data.candidates||[]).map(x=>`<article class="curriculum-record"><div><b>${ar?'الصفحة':'Page'} ${x.source_page} · ${escapeReviewText(x.suggested_field)}</b><small>${escapeReviewText(x.source_excerpt)}</small><div class="test-builder-grid"><input id="ev-unit-${x.id}" placeholder="${ar?'الوحدة':fr?'Unité':'Unit'}" value="${escapeReviewText(x.unit||'')}"><input id="ev-lesson-${x.id}" placeholder="${ar?'الدرس':fr?'Leçon':'Lesson'}" value="${escapeReviewText(x.lesson||'')}"><input id="ev-comp-${x.id}" placeholder="${ar?'الكفاءة':fr?'Compétence':'Competency'}" value="${escapeReviewText(x.competency||'')}"><input id="ev-grade-${x.id}" placeholder="${ar?'السنة الدراسية':fr?'Niveau':'Grade'}" value="${escapeReviewText(x.grade||'')}"><input id="ev-subject-${x.id}" placeholder="${ar?'المادة':fr?'Matière':'Subject'}" value="${escapeReviewText(x.subject||'')}"><select id="ev-term-${x.id}"><option value="">${ar?'الفصل — غير محدد':fr?'Trimestre — non défini':'Term — unset'}</option>${[1,2,3].map(n=>`<option value="${n}" ${x.term===n?'selected':''}>${n}</option>`).join('')}</select></div><textarea id="ev-notes-${x.id}" placeholder="${ar?'ملاحظات المراجع':fr?'Notes du réviseur':'Reviewer notes'}">${escapeReviewText(x.reviewer_notes||'')}</textarea><button class="secondary-btn" onclick="saveCurriculumEvidenceCandidate('${x.id}')">${ar?'حفظ كمرشح':fr?'Enregistrer la proposition':'Save candidate'}</button><small>${ar?'الحالة: قيد المراجعة — غير معتمد رسمياً':fr?'En attente — non vérifié officiellement':'Pending review — not officially verified'} · ${escapeReviewText(x.source_filename||'')}</small></div></article>`).join('');
 mount.innerHTML=`<section class="panel"><h3>${title}</h3><p>${ar?'المقتطف مرتبط برقم الصفحة. املأ الحقول بعد مقارنة الوثيقة الأصلية. الحفظ لا يثبت المطابقة ولا يحدّث سجل المنهاج.':fr?'Chaque extrait conserve son numéro de page. Vérifiez-le dans le document original. Aucun alignement officiel n’est certifié.':'Each excerpt retains its page number. Check it against the original document. Saving does not certify alignment or update the curriculum registry.'}</p>${rows||`<div class="empty-note">${ar?'لم تُستخرج مرشحات بعد.':fr?'Aucune proposition extraite.':'No candidates extracted yet.'}</div>`}<p class="notice">${data.count||0} · ${ar?'تم التحقق رسمياً: 0':'Officially verified: 0'} · Auto-publish: off</p></section>`;
}
async function saveCurriculumEvidenceCandidate(id){
 const get=k=>document.getElementById(`ev-${k}-${id}`)?.value||'';const term=get('term');const payload={unit:get('unit'),lesson:get('lesson'),competency:get('comp'),grade:get('grade'),subject:get('subject'),term:term?Number(term):null,status:'reviewed_candidate',reviewer_notes:get('notes')};
 try{const r=await fetch(`${apiBase()}/api/v1/archive/curriculum-evidence-candidates/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Save failed');toast(lang==='ar'?'تم حفظ المرشح دون اعتماده رسمياً':lang==='fr'?'Proposition enregistrée, non certifiée':'Candidate saved, not officially verified')}catch(e){toast(e.message)}
}
async function analyzePdfLayout(id){
 const mount=$('#pdfLayoutMount');if(mount)mount.innerHTML='<p class="notice">Analyzing PDF layout…</p>';
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/analyze-layout`,{method:'POST'});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Layout analysis failed');renderPdfLayout(data);toast(lang==='ar'?'اكتمل تحليل بنية الصفحات':lang==='fr'?'Analyse de mise en page terminée':'Page layout analysis completed')}catch(e){if(mount)mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`;toast(e.message)}
}
async function loadPdfLayout(id){
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/layout`);if(!r.ok)return;renderPdfLayout(await r.json())}catch(e){}
}
function renderPdfLayout(data){
 const mount=$('#pdfLayoutMount');if(!mount)return;const ar=lang==='ar',fr=lang==='fr',s=data.summary||{};const title=ar?'تحليل بنية الملف':fr?'Analyse de structure':'Document structure analysis';
 const rows=(data.pages||[]).map(p=>`<article class="pdf-layout-page"><b>${ar?'الصفحة':'Page'} ${p.page}</b><span>${ar?'مناطق رياضية':'Math hints'}: ${p.math_region_count}</span><span>${ar?'جداول':'Tables'}: ${p.table_count}</span><span>${ar?'صور':'Images'}: ${p.embedded_image_count}</span><span>${ar?'رسوم متجهة':'Vector drawings'}: ${p.vector_drawing_count}</span>${(p.math_regions||[]).map(m=>`<pre>${escapeReviewText(m.text)}</pre>`).join('')}</article>`).join('');
 mount.innerHTML=`<section class="pdf-layout-panel"><h4>${title}</h4><div class="pdf-layout-summary"><span>${ar?'صفحات محللة':'Pages analyzed'}: ${s.pages_analyzed||0}</span><span>${ar?'مناطق رياضية':'Math hints'}: ${s.math_region_count||0}</span><span>${ar?'جداول':'Tables'}: ${s.table_count||0}</span><span>${ar?'صور ورسوم':'Images & drawings'}: ${(s.image_count||0)+(s.vector_drawing_count||0)}</span></div>${rows||''}<p class="notice">${ar?'هذه مؤشرات آلية وليست إعادة بناء دقيقة للمعادلات أو الجداول. راجع الصفحات بصرياً قبل اعتماد أي سؤال أو حل.':fr?'Ces indices sont heuristiques. Vérifiez visuellement les pages avant toute validation.':'Heuristic hints only: equations and tables are not reconstructed reliably. Visually inspect source pages before approving any question or solution.'}</p></section>`;
}

async function extractPdfCandidates(id){
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-review/${id}/extract-candidates`,{method:'POST'});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Extraction failed');await loadPdfQuestionCandidates(id);toast(lang==='ar'?`تم إنشاء ${data.created} مرشحاً للمراجعة`:lang==='fr'?`${data.created} propositions détectées`:`${data.created} candidates detected`)}catch(e){toast((lang==='ar'?'تعذر استخراج الأسئلة: ':lang==='fr'?'Détection impossible : ':'Candidate extraction failed: ')+e.message)}
}
async function loadPdfQuestionCandidates(id){
 const mount=$('#pdfCandidateMount');if(!mount)return;
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-question-candidates?document_id=${encodeURIComponent(id)}`);const data=await r.json();if(!r.ok)throw new Error(data.detail||'API');pdfQuestionCandidates=data.candidates||[];const ar=lang==='ar',fr=lang==='fr';const labels=ar?{title:'مرشحات الأسئلة',empty:'لم تُكتشف أسئلة بعد.',q:'نص السؤال',a:'الإجابة أو الحل المقترح',grade:'السنة',subject:'المادة',term:'الفصل',topic:'الموضوع',year:'سنة الامتحان',type:'نوع الامتحان',status:'الحالة',pending:'بانتظار المراجعة',approved:'مسموح بالإدخال اليدوي بعد التحقق من الحقوق',rejected:'مرفوض',notes:'ملاحظات',save:'حفظ المرشح',warning:'لا تُضاف هذه المرشحات إلى بنك التمارين تلقائياً.'}:fr?{title:'Questions candidates',empty:'Aucune question détectée.',q:'Énoncé',a:'Réponse ou solution proposée',grade:'Niveau',subject:'Matière',term:'Trimestre',topic:'Thème',year:'Année de l’examen',type:'Type',status:'Statut',pending:'En attente',approved:'Autorisé pour saisie manuelle après vérification des droits',rejected:'Rejeté',notes:'Notes',save:'Enregistrer',warning:'Aucun candidat n’est ajouté automatiquement à la banque.'}:{title:'Question candidates',empty:'No candidates detected yet.',q:'Question text',a:'Suggested answer or solution',grade:'Grade',subject:'Subject',term:'Term',topic:'Topic',year:'Exam year',type:'Exam type',status:'Status',pending:'Pending review',approved:'Eligible for manual entry after rights check',rejected:'Rejected',notes:'Reviewer notes',save:'Save candidate',warning:'Candidates are not automatically added to the exercise bank.'};
 mount.innerHTML=`<section class="candidate-panel"><h4>${labels.title} (${pdfQuestionCandidates.length})</h4>${pdfQuestionCandidates.length?pdfQuestionCandidates.map(c=>`<article class="candidate-card"><label>${labels.q}<textarea id="cq-${c.id}" rows="4">${escapeReviewText(c.candidate_text||'')}</textarea></label><label>${labels.a}<textarea id="ca-${c.id}" rows="3">${escapeReviewText(c.suggested_answer||'')}</textarea></label><div class="candidate-meta-grid"><label>${labels.grade}<input id="cg-${c.id}" value="${escapeReviewText(c.grade||'')}" placeholder="${ar?'مثال: الرابعة متوسط':'e.g. 4AM'}"></label><label>${labels.subject}<input id="cs-${c.id}" value="${escapeReviewText(c.subject||'')}"></label><label>${labels.term}<select id="ct-${c.id}"><option value="">—</option>${[1,2,3].map(t=>`<option value="${t}" ${String(c.term)===String(t)?'selected':''}>${t}</option>`).join('')}</select></label><label>${labels.topic}<input id="cp-${c.id}" value="${escapeReviewText(c.topic||'')}"></label><label>${labels.year}<input id="cy-${c.id}" type="number" min="2000" max="2100" value="${c.exam_year||''}"></label><label>${labels.type}<select id="ce-${c.id}">${[['BEM','BEM'],['BAC','BAC'],['term_test',ar?'اختبار فصلي':fr?'Devoir trimestriel':'Term test'],['homework',ar?'فرض منزلي':fr?'Devoir maison':'Homework'],['practice',ar?'تدريبي':fr?'Entraînement':'Practice'],['other',ar?'آخر':fr?'Autre':'Other']].map(([v,l])=>`<option value="${v}" ${(c.exam_type||'other')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label>${labels.status}<select id="cst-${c.id}"><option value="pending_review" ${c.status==='pending_review'?'selected':''}>${labels.pending}</option><option value="approved_for_manual_entry" ${c.status==='approved_for_manual_entry'?'selected':''}>${labels.approved}</option><option value="rejected" ${c.status==='rejected'?'selected':''}>${labels.rejected}</option></select></label><label>${labels.notes}<textarea id="cn-${c.id}" rows="2">${escapeReviewText(c.reviewer_notes||'')}</textarea></label><div class="candidate-analysis-tools"><select id="analysis-lang-${c.id}" aria-label="Analysis language"><option value="ar" ${lang==='ar'?'selected':''}>العربية</option><option value="fr" ${lang==='fr'?'selected':''}>Français</option><option value="en" ${lang==='en'?'selected':''}>English</option></select><button class="secondary-btn" onclick="analyzePdfCandidate('${c.id}')">${ar?'فهم السؤال واقتراح خطوات الحل':fr?'Analyser la question et proposer une démarche':'Understand question & suggest solution steps'}</button></div><div id="analysis-${c.id}" class="candidate-analysis-result"></div><button class="secondary-btn" onclick="savePdfCandidate('${c.id}')">${labels.save}</button><small>Page ${c.source_page||'—'} · ${escapeReviewText(c.source_filename||'')} · ${c.auto_published?'published':'not published'}</small></article>`).join(''):`<div class="empty-note">${labels.empty}</div>`}<p class="notice">${labels.warning}</p></section>`;for(const c of pdfQuestionCandidates)loadPdfCandidateAnalysis(c.id);
 }catch(e){mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`}
}
async function analyzePdfCandidate(id){
 const language=document.getElementById('analysis-lang-'+id)?.value||lang;
 const mount=document.getElementById('analysis-'+id);if(mount)mount.innerHTML='<p class="notice">Analyzing question…</p>';
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-question-candidates/${id}/analyze`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Analysis failed');renderPdfCandidateAnalysis(data.analysis);toast(language==='ar'?'تم إعداد تحليل أولي للمراجعة':language==='fr'?'Analyse préparée pour révision':'Draft analysis ready for review')}catch(e){if(mount)mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`;toast(e.message)}
}
async function loadPdfCandidateAnalysis(id){
 const language=document.getElementById('analysis-lang-'+id)?.value||lang;
 try{const r=await fetch(`${apiBase()}/api/v1/archive/pdf-question-candidates/${id}/analysis?language=${language}`);if(r.ok)renderPdfCandidateAnalysis(await r.json())}catch(e){}
}
function renderPdfCandidateAnalysis(data){
 const mount=document.getElementById('analysis-'+data.candidate_id);if(!mount)return;
 const ar=data.language==='ar',fr=data.language==='fr';const heading=ar?'تحليل السؤال وخطة الحل':fr?'Analyse et démarche de résolution':'Question analysis & solution plan';
 mount.innerHTML=`<section class="candidate-analysis"><div class="learning-meta"><b>${heading}</b><span>${data.mode==='groq'?'Groq':'Heuristic'} · ${ar?'مسودة':fr?'Brouillon':'Draft'}</span></div><pre>${escapeReviewText(data.analysis_text||'')}</pre><p class="notice">${ar?'مراجعة الأستاذ مطلوبة. هذا التحليل لا يمثل تصحيحاً رسمياً ولا يُضاف إلى بنك التمارين.':fr?'Révision par l’enseignant requise. Cette analyse n’est pas un corrigé officiel.':'Teacher review required. This is not an official answer key and is not inserted into the exercise bank.'}</p></section>`;
}

