async function generateCurriculumExam(){
 const mount=document.getElementById('currExamResult');if(!mount)return;
 const payload={grade:bankTestSelection.grade||grade,subject:bankTestSelection.subject,term:Number(bankTestSelection.term),question_count:Number(document.getElementById('currExamCount')?.value||3),language:'auto'};
 if(!payload.subject||!payload.term){mount.innerHTML='<p class="notice">'+(lang==='ar'?'اختر المادة والفصل أولاً من منشئ الاختبارات أعلاه.':lang==='fr'?'Choisissez d’abord la matière et le trimestre.':'Choose the subject and term in the test builder above first.')+'</p>';return}
 mount.innerHTML='<p class="notice">'+(lang==='ar'?'جارٍ إعداد الاختبار…':lang==='fr'?'Création du sujet…':'Building assessment…')+'</p>';
 try{const r=await fetch(`${apiBase()}/api/v1/learning/exam-builder`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:(data.detail?.message||'Not enough matching questions'));window.generatedCurriculumPaper=data.paper;renderCurriculumExamVersions(data.paper)}catch(e){mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`}
}
function renderCurriculumExamVersions(paper){
 const mount=document.getElementById('currExamResult');if(!mount)return;const ar=lang==='ar',fr=lang==='fr';const p=paper.student_version,t=paper.teacher_version;
 mount.innerHTML=`<div class="exam-version-actions"><button class="primary-btn" onclick="showCurriculumExamVersion('student')">${ar?'نسخة التلميذ':fr?'Version élève':'Student copy'}</button><button class="secondary-btn" onclick="showCurriculumExamVersion('teacher')">${ar?'نسخة الأستاذ والحلول':fr?'Version enseignant et corrigé':'Teacher copy & key'}</button></div><div id="currExamVersion" class="curriculum-exam-version"></div><p class="notice">${escapeReviewText(paper.curriculum_policy_note)} ${ar?'تتطلب مراجعة الأستاذ قبل الطباعة أو الاعتماد.':fr?'Révision de l’enseignant requise avant utilisation.':'Teacher review required before printing or use.'}</p>`;
 showCurriculumExamVersion('student');
}
function showCurriculumExamVersion(kind){
 const paper=window.generatedCurriculumPaper,mount=document.getElementById('currExamVersion');if(!paper||!mount)return;const ar=lang==='ar',fr=lang==='fr',teacher=kind==='teacher';const rows=teacher?paper.teacher_version.answer_key:paper.student_version.questions;
 mount.innerHTML=`<h3>${escapeReviewText(teacher?paper.teacher_version.title:paper.student_version.title)}</h3><p>${paper.grade} · ${escapeReviewText(paper.subject)} · ${ar?'الفصل':'Term'} ${paper.term} · ${String(paper.language).toUpperCase()} · /20</p>${rows.map(q=>`<article class="question-card"><div class="learning-meta"><b>${ar?'السؤال':'Question'} ${q.number}</b><span>${q.points} ${ar?'نقطة':'pts'}</span></div><p>${escapeReviewText(q.question)}</p>${(q.choices||[]).map((c,i)=>`<p>${String.fromCharCode(65+i)}. ${escapeReviewText(c)}</p>`).join('')}${teacher?`<div class="answer-review-card"><b>${ar?'الإجابة':'Answer'}:</b> ${escapeReviewText(q.answer??(q.answer_index!=null?q.choices[q.answer_index]:'—'))}<p>${escapeReviewText(q.explanation||'')}</p>${(q.solution_steps||[]).map((x,i)=>`<p>${i+1}. ${escapeReviewText(x)}</p>`).join('')}</div>`:''}</article>`).join('')}<button class="secondary-btn" onclick="window.print()">${ar?'طباعة النسخة المعروضة':fr?'Imprimer la version':'Print displayed copy'}</button>`;
}

function externalExamLibraryPanel(){
 const ar=lang==='ar',fr=lang==='fr',d=externalExamLibrary||{sources:[],records:[],scope:{years:[2022,2023,2024,2025,2026]}};
 const title=ar?'مكتبة الفروض والاختبارات والحلول من المواقع الجزائرية':fr?'Bibliothèque externe des devoirs, examens et corrigés':'External Algerian homework, exams & solutions library';
 const desc=ar?'فهرس موحد لمصادر 2022–2026 حسب الطور والسنة. تفتح الملفات من مواقعها الأصلية ولا تنسخ محلياً دون إذن.':fr?'Index unifié 2022–2026 par cycle et niveau. Les fichiers restent hébergés par leurs éditeurs.':'Unified 2022–2026 source index by stage and grade. Files remain hosted by their publishers.';
 return `<section class="panel exam-archive-panel"><div class="learning-meta"><b>🌐 ${title}</b><span>${(d.records||[]).length} ${ar?'وثيقة مكتشفة':fr?'documents':'discovered items'}</span></div><p>${desc}</p><div class="test-builder-grid"><label>${ar?'الطور':fr?'Cycle':'Stage'}<select id="extLibStage"><option value="all">${ar?'الكل':'All'}</option><option value="primary">${ar?'ابتدائي':'Primary'}</option><option value="middle">${ar?'متوسط':'Middle'}</option><option value="secondary">${ar?'ثانوي':'Secondary'}</option></select></label><label>${ar?'السنة الدراسية':'Grade'}<select id="extLibGrade"><option value="all">${ar?'كل السنوات الدراسية':'All grades'}</option>${Object.values(d.scope?.grades||{}).flat().map(g=>`<option>${escapeReviewText(g)}</option>`).join('')}</select></label><label>${ar?'السنة':fr?'Année':'Year'}<select id="extLibYear"><option value="all">${ar?'كل السنوات':'All years'}</option>${(d.scope?.years||[2022,2023,2024,2025,2026]).map(y=>`<option>${y}</option>`).join('')}</select></label><label>${ar?'نوع الوثيقة':'Document type'}<select id="extLibType"><option value="all">${ar?'الكل':'All'}</option><option value="homework">${ar?'فرض':'Homework'}</option><option value="test">${ar?'اختبار':'Test'}</option><option value="exam">${ar?'امتحان':'Exam'}</option><option value="solution">${ar?'حل/تصحيح':'Solution'}</option></select></label></div><div class="test-builder-actions"><button class="primary-btn" onclick="searchExternalExamLibrary()">${ar?'بحث في المكتبة':'Search library'}</button></div><div id="externalExamLibraryResults" class="archive-source-list">${(d.sources||[]).map(x=>`<article class="archive-source"><div><b>${escapeReviewText(x.name)}</b><small>${escapeReviewText(x.note)}</small></div><a href="${escapeReviewText(x.url)}" target="_blank" rel="noopener noreferrer">${ar?'فتح المصدر':'Open source'} ↗</a></article>`).join('')}</div><p class="notice">${ar?'فهرس المصادر جاهز، لكن الاتصال بالمواقع تعذر في بيئة البناء؛ لم يتم تنزيل ملفات PDF. شغّل أداة المزامنة في بيئة متصلة. لا تنشر ملفات محمية دون إذن.':'Source directory is ready, but network access failed in this build environment; no PDFs were downloaded. Run the sync tool in a network-enabled environment. Do not republish protected files without permission.'}</p></section>`;
}
function searchExternalExamLibrary(){const m=document.getElementById('externalExamLibraryResults');if(!m)return;const d=externalExamLibrary||{},s=document.getElementById('extLibStage')?.value||'all',g=document.getElementById('extLibGrade')?.value||'all',y=document.getElementById('extLibYear')?.value||'all',t=document.getElementById('extLibType')?.value||'all',ar=lang==='ar';const rows=(d.records||[]).filter(x=>(s==='all'||x.stage===s||x.stage==='all')&&(g==='all'||x.grade===g||x.grade==='all')&&(y==='all'||(x.years||[]).includes(Number(y)))&&(t==='all'||(x.document_types||[]).includes(t)));m.innerHTML=rows.length?rows.map(x=>{const u=x.pdf_url||x.url||x.source_page_url;return `<article class="archive-source"><div><b>${escapeReviewText(x.title||x.source_page_label||x.id)}</b><small>${escapeReviewText(x.source_name||x.source_host||'')} · ${escapeReviewText(x.grade||'')} · ${escapeReviewText(x.format||'PDF')} · ${ar?'الحل يحتاج تحققاً':'Solution requires verification'}</small></div>${/^https:\/\//i.test(u||'')?`<a href="${escapeReviewText(u)}" target="_blank" rel="noopener noreferrer">${x.pdf_url?(ar?'تحميل PDF':'Download PDF'):(ar?'فتح المصدر':'Open source')} ↗</a>`:`<span class="pill">${ar?'الرابط غير متاح':'Link unavailable'}</span>`}${x.pdf_url&&/^https:\/\//i.test(x.source_page_url||x.url||'')?`<a class="source-fallback-link" href="${escapeReviewText(x.source_page_url||x.url)}" target="_blank" rel="noopener noreferrer">${ar?'فتح صفحة المصدر إذا تعذر التحميل':'Open source page if download fails'} ↗</a>`:''}</article>`}).join(''):(d.sources||[]).filter(x=>(s==='all'||x.stage==='all'||x.stage===s)&&(g==='all'||x.grade==='all'||x.grade===g)).map(x=>`<article class="archive-source"><div><b>${escapeReviewText(x.name)}</b><small>${escapeReviewText(x.note)}</small></div><a href="${escapeReviewText(x.url)}" target="_blank" rel="noopener noreferrer">${ar?'فتح المصدر':'Open source'} ↗</a></article>`).join('')||`<div class="empty-note">${ar?'لا توجد مصادر مطابقة.':'No matching sources.'}</div>`;}

function claudeContentDraftPanel(){const ar=lang==='ar',fr=lang==='fr';return `<section class="panel claude-draft-panel"><div class="learning-meta"><b>✦ ${ar?'مولّد وضعيات وتمارين بمساعدة Claude':'Claude-assisted practice and integrative task drafts'}</b><span class="pill">${ar?'يتطلب إعداد الخادم':'Server setup required'}</span></div><p>${ar?'ينشئ مسودة تعليمية أصلية حسب السنة والمادة والفصل، مع حلول وسلم تقييم. لا تُضاف إلى المكتبة تلقائياً قبل مراجعة الأستاذ.':fr?'Génère un brouillon pédagogique original avec corrigé et barème. Révision enseignante obligatoire.':'Creates original grade- and subject-specific drafts with worked answers and a rubric. Teacher review is required before publication.'}</p><div class="test-builder-grid"><label>${ar?'الموضوع / المحور':'Topic'}<input id="claudeDraftTopic" placeholder="${ar?'مثال: التناسبية أو التحولات الكيميائية':'e.g. proportionality or chemical changes'}"></label><label>${ar?'نوع المحتوى':'Draft type'}<select id="claudeDraftTask"><option value="integrative">${ar?'وضعية إدماجية':'Integrative situation'}</option><option value="exercise">${ar?'سلسلة تمارين':'Exercise set'}</option></select></label></div><button class="secondary-btn" onclick="generateClaudeDraft()">${ar?'إنشاء مسودة عبر Claude':'Generate Claude draft'} ✦</button><div id="claudeDraftResult"></div><small>${ar?'يلزم وضع ANTHROPIC_API_KEY في الخادم، وليس داخل التطبيق أو ملف APK.':'Set ANTHROPIC_API_KEY on the server only; never embed it in the app or APK.'}</small></section>`}
async function generateClaudeDraft(){const mount=document.getElementById('claudeDraftResult');const topic=document.getElementById('claudeDraftTopic')?.value.trim();if(!topic){toast(lang==='ar'?'اكتب الموضوع أولاً':'Enter a topic first');return}mount.innerHTML='<p class="notice">'+(lang==='ar'?'جارٍ إنشاء المسودة…':'Generating draft…')+'</p>';try{const r=await fetch(`${apiBase()}/api/v1/ai/claude-content`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task:document.getElementById('claudeDraftTask')?.value||'integrative',grade:bankTestSelection.grade||grade,subject:bankTestSelection.subject||subjectsForCurrentGrade()[0],topic,term:Number(bankTestSelection.term)||1,language:lang})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Claude service unavailable');mount.innerHTML=`<div class="notice">${lang==='ar'?'مسودة غير منشورة — تتطلب مراجعة الأستاذ':'Unpublished draft — teacher review required'}</div><pre class="claude-draft-output">${escapeReviewText(JSON.stringify(data.draft,null,2))}</pre>`}catch(e){mount.innerHTML=`<p class="notice">${escapeReviewText(e.message)}</p>`}}

function testBankHomePage(){
 const ar=lang==='ar',fr=lang==='fr';
 const L=ar?{title:'اختبارات فصلية حسب السنة والمادة',desc:'أنشئ اختباراً تدريبياً من بنك المنصة، ثم احصل على علامة من 20 وتحليل لنقاط القوة والجوانب التي تحتاج إلى مراجعة.',grade:'السنة الدراسية',subject:'المادة',term:'الفصل',all:'كل الفصول',count:'عدد الأسئلة',start:'إنشاء الاختبار وبدؤه',empty:'اختر السنة والمادة ثم ابدأ الاختبار.',history:'آخر النتائج',none:'لا توجد نتائج محفوظة بعد.',notice:'الاختبارات مولّدة من تمارين المنصة المتاحة لهذه المادة والسنة. المحتوى تدريبي وليس اختباراً وزارياً رسمياً.'}:fr?{title:'Tests par niveau et matière',desc:'Créez un test à partir de la banque, obtenez une note sur 20 et repérez les points forts et les notions à revoir.',grade:'Niveau scolaire',subject:'Matière',term:'Trimestre',all:'Tous les trimestres',count:'Nombre de questions',start:'Créer et commencer',empty:'Choisissez le niveau et la matière.',history:'Résultats récents',none:'Aucun résultat enregistré.',notice:'Tests générés à partir des exercices disponibles. Contenu d’entraînement non officiel.'}:{title:'Term tests by grade and subject',desc:'Build a practice test from the platform bank, receive a mark out of 20, and review strengths and topics that need more work.',grade:'School grade',subject:'Subject',term:'Term',all:'All terms',count:'Question count',start:'Build and start test',empty:'Choose a grade and subject to begin.',history:'Recent results',none:'No saved results yet.',notice:'Tests are assembled from available platform exercises. Practice content only; not official Ministry papers.'};
 const g=bankTestSelection.grade||grade;const available=exerciseBankRecords.filter(x=>x.grade===g);const subs=[...new Set(available.map(x=>x.subject))];const sub=subs.includes(bankTestSelection.subject)?bankTestSelection.subject:(subs[0]||'');
 bankTestSelection.grade=g;bankTestSelection.subject=sub;
 const history=readBankTestHistory();
 return `${sectionHead(L.title,g)}${typeof dzexamsPanel==='function'?dzexamsPanel(g):''}<details class="panel admin-sources" ontoggle="if(this.open&&!window.__pdfLoaded){window.__pdfLoaded=1;loadPdfReviewDocuments()}"><summary><b>⚙️ ${lang==='ar'?'مصادر خارجية وأدوات المشرف (اختياري)':lang==='fr'?'Sources externes et outils admin (facultatif)':'External sources & admin tools (optional)'}</b></summary>${externalExamLibraryPanel()}${examLibraryPanel()}${pdfReviewPanel()}${schoolAssessmentsArchivePanel()}${examArchivePanel()}</details><div class="panel test-builder"><p>${L.desc}</p><div class="test-builder-grid"><label>${L.grade}<select id="bankTestGrade" onchange="changeBankTestGrade(this.value)">${levels.primary.concat(levels.middle,levels.secondary).map(x=>`<option ${x===g?'selected':''}>${x}</option>`).join('')}</select></label><label>${L.subject}<select id="bankTestSubject" onchange="bankTestSelection.subject=this.value">${subs.map(x=>`<option ${x===sub?'selected':''}>${x}</option>`).join('')}</select></label><label>${L.term}<select id="bankTestTerm" onchange="bankTestSelection.term=this.value"><option value="all" ${bankTestSelection.term==='all'?'selected':''}>${L.all}</option><option value="1" ${bankTestSelection.term==='1'?'selected':''}>${ar?'الأول':fr?'1er':'First'}</option><option value="2" ${bankTestSelection.term==='2'?'selected':''}>${ar?'الثاني':fr?'2e':'Second'}</option><option value="3" ${bankTestSelection.term==='3'?'selected':''}>${ar?'الثالث':fr?'3e':'Third'}</option></select></label><label>${L.count}<select id="bankTestCount" onchange="bankTestSelection.count=this.value">${['5','10','15','20'].map(x=>`<option value="${x}" ${bankTestSelection.count===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="learning-meta"><span>${available.length} ${ar?'تمريناً متاحاً في هذه السنة':fr?'exercices disponibles':'available exercises for this grade'}</span><span>${sub}</span></div><div class="test-builder-actions"><button class="primary-btn" onclick="startBankTest()" ${!sub?'disabled':''}>${L.start} →</button><button class="secondary-btn" onclick="startPreparedTermExam()" ${!sub||bankTestSelection.term==='all'?'disabled':''}>${ar?'بدء الاختبار الفصلي الجاهز':fr?'Lancer le sujet trimestriel':'Start prepared term paper'} ↗</button><button class="secondary-btn" onclick="startIntegrativeAssessment()" ${!sub||bankTestSelection.term==='all'?'disabled':''}>${ar?'وضعية إدماجية مركبة':fr?'Situation d’intégration':'Integrative situation'} ✦</button></div><div class="notice">${L.notice} ${ar?'الاختبار الفصلي الجاهز يستخدم جميع أسئلة الفصل المتاحة مع سلم تنقيط وحلول مفصلة.':fr?'Le sujet prêt utilise toutes les questions du trimestre avec barème et corrigé détaillé.':'The prepared paper uses all available term questions with a 20-point marking scheme and worked answer key.'}</div><div id="bankTestMount">${L.empty}</div></div>${curriculumGovernancePanel()}${curriculumExamBuilderPanel()}${claudeContentDraftPanel()}${window.SM_STUDY_DOWNLOAD?window.SM_STUDY_DOWNLOAD.panelHtml():''}<section class="panel test-history"><h3>${L.history}</h3>${history.length?history.slice(0,8).map(x=>`<div class="activity-row"><div><b>${x.subject}</b><small>${x.grade} · ${x.date} · ${x.term==='all'?(ar?'كل الفصول':fr?'Tous les trimestres':'All terms'):((ar?'الفصل ':fr?'Trimestre ':'Term ')+x.term)}</small></div><strong>${x.mark}/20</strong></div>`).join(''):`<div class="empty-note">${L.none}</div>`}</section>`;
}
function renderTestBankHome(){if(page==='tests'){ $('#pageContent').innerHTML=testBankHomePage();if(window.SM_STUDY_DOWNLOAD)window.SM_STUDY_DOWNLOAD.refreshPanel(); }}

function changeBankTestGrade(value){bankTestSelection.grade=value;bankTestSelection.subject='';renderTestBankHome()}
function readAllBankTestHistory(){try{const x=JSON.parse(localStorage.getItem('smSchoolTestHistory')||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function readBankTestHistory(){const learner=activeLearner();return readAllBankTestHistory().filter(x=>x.learnerId===learner.id||(!x.learnerId&&learner.id==='default'))}
function startBankTest(){const {grade:g,subject,term,count}=bankTestSelection;let pool=exerciseBankRecords.filter(x=>x.grade===g&&x.subject===subject&&(term==='all'||String(x.term)===term));if(!pool.length){toast(lang==='ar'?'لا توجد تمارين لهذا الاختيار.':lang==='fr'?'Aucun exercice pour cette sélection.':'No exercises match this selection.');return}const selected=shuffleList(pool).slice(0,Math.min(Number(count)||10,pool.length)).map(q=>{let choices=q.choices||[],answer=q.answer_index;if(choices.length){const order=shuffleList(choices.map((_,i)=>i));choices=order.map(i=>q.choices[i]);answer=order.indexOf(q.answer_index)}return {...q,choices,answer_index:answer}});window.activeBankTest={grade:g,subject,term,items:selected,submitted:false,startedAt:Date.now()};renderActiveBankTest();}
function startPreparedTermExam(){
 const {grade:g,subject,term}=bankTestSelection;
 if(term==='all'){toast(lang==='ar'?'اختر فصلاً محدداً أولاً.':lang==='fr'?'Choisissez un trimestre.':'Choose a specific term first.');return}
 const matches=termExamPapers.filter(x=>x.grade===g&&x.subject===subject&&String(x.term)===String(term));
 const fresh=matches.filter(x=>x.id!==window.lastTermPaperId),pool=fresh.length?fresh:matches,paper=pool[Math.floor(Math.random()*pool.length)];
 if(paper)window.lastTermPaperId=paper.id;
 if(!paper){toast(lang==='ar'?'الاختبار الفصلي غير متاح لهذا الاختيار.':lang==='fr'?'Sujet trimestriel indisponible.':'Prepared term paper unavailable for this selection.');return}
 const byId=new Map(exerciseBankRecords.map(q=>[q.id,q]));
 const selected=paper.question_ids.map(id=>byId.get(id)).filter(Boolean).map(q=>{const choices=q.choices||[],answer=q.answer_index;if(choices.length){const order=shuffleList(choices.map((_,i)=>i));return {...q,choices:order.map(i=>choices[i]),answer_index:order.indexOf(answer)}}return {...q}});
 if(selected.length!==paper.question_count){toast(lang==='ar'?'تعذر تحميل جميع أسئلة الاختبار.':lang==='fr'?'Impossible de charger toutes les questions.':'Could not load every paper question.');return}
 window.activeBankTest={grade:g,subject,term,items:selected,submitted:false,startedAt:Date.now(),paperId:paper.id,paperTitle:paper.title,durationMinutes:paper.duration_minutes,totalPoints:20,prepared:true};
 renderActiveBankTest();
}
function startIntegrativeAssessment(){
 const {grade:g,subject,term}=bankTestSelection;
 if(term==='all'){toast(lang==='ar'?'اختر فصلاً محدداً أولاً.':lang==='fr'?'Choisissez un trimestre.':'Choose a specific term first.');return}
 const paper=integrativeAssessments.find(x=>x.grade===g&&x.subject===subject&&String(x.term)===String(term));
 if(!paper){toast(lang==='ar'?'الوضعية الإدماجية غير متاحة لهذا الاختيار.':lang==='fr'?'Situation indisponible.':'Integrative situation unavailable.');return}
 const byId=new Map(exerciseBankRecords.map(q=>[q.id,q]));
 const selected=paper.question_ids.map(id=>byId.get(id)).filter(Boolean).map(q=>{const choices=q.choices||[],answer=q.answer_index;if(choices.length){const order=shuffleList(choices.map((_,i)=>i));return {...q,choices:order.map(i=>choices[i]),answer_index:order.indexOf(answer)}}return {...q}});
 if(selected.length!==paper.question_count){toast(lang==='ar'?'تعذر تحميل جميع أسئلة الوضعية.':lang==='fr'?'Questions indisponibles.':'Could not load all situation questions.');return}
 window.activeBankTest={grade:g,subject,term,items:selected,submitted:false,startedAt:Date.now(),paperId:paper.id,paperTitle:paper.title,durationMinutes:paper.duration_minutes,totalPoints:20,prepared:true,integrative:true,integrativePaper:paper};
 renderActiveBankTest();
}
function renderActiveBankTest(){const mount=document.getElementById('bankTestMount'),test=window.activeBankTest;if(!mount||!test)return;const ar=lang==='ar',fr=lang==='fr';mount.innerHTML=`${test.integrative?`<section class="panel integrative-situation"><div class="pill">${ar?'وضعية إدماجية تدريبية':fr?'Situation d’intégration':'Integrative practice situation'}</div><h3>${escapeReviewText(test.integrativePaper.title)}</h3><p>${escapeReviewText(test.integrativePaper.situation_i18n?.[lang]||test.integrativePaper.situation)}</p><h4>${ar?'المهمة الكتابية الإضافية':fr?'Production écrite complémentaire':'Written extension'}</h4><p>${escapeReviewText(test.integrativePaper.written_task_i18n?.[lang]||test.integrativePaper.written_task)}</p><small>${ar?'هذه المهمة للتقييم الذاتي ولا تدخل في التصحيح الآلي.':fr?'Cette tâche est en autoévaluation et n’est pas notée automatiquement.':'This extension is self-reviewed and is not automatically graded.'}</small><textarea id="integrativeWrittenResponse" rows="4" placeholder="${ar?'اكتب إجابتك هنا للمقارنة مع عناصر الحل النموذجي':fr?'Rédigez votre réponse ici':'Write your response here'}"></textarea></section>`:''}<div class="bank-test-head"><b>${test.integrative?(ar?'اختبار الوضعية الإدماجية':fr?'Évaluation intégrative':'Integrative assessment'):test.prepared?(ar?'اختبار فصلي تدريبي':fr?'Sujet trimestriel d’entraînement':'Prepared term practice paper'):test.grade} · ${test.subject} · ${ar?'الفصل':'Term'} ${test.term}</b><span>${test.items.length} ${ar?'سؤالاً':fr?'questions':'questions'}${test.durationMinutes?' · '+test.durationMinutes+' '+(ar?'دقيقة مقترحة':fr?'min suggérées':'suggested min'):''} · /20</span></div><div class="notice">${ar?'أجب عن جميع الأسئلة ثم اضغط إنهاء الاختبار.':fr?'Répondez aux questions puis terminez le test.':'Answer the questions, then submit the test.'}</div>${test.items.map((q,i)=>`<article class="question-card"><div class="learning-meta"><small>${ar?'السؤال':fr?'Question':'Question'} ${i+1} · ${q.difficulty||''}</small><small>${q.topic||''}</small></div><h4>${i+1}. ${q.question}</h4>${q.question_type==='numeric'?`<label class="typed-answer"><span>${ar?'إجابتك':fr?'Votre réponse':'Your answer'}</span><input type="text" inputmode="decimal" autocomplete="off" name="bankTestQ${i}" placeholder="${ar?'اكتب الإجابة':fr?'Saisir la réponse':'Enter your answer'}"></label>`:`<div class="answer-options">${q.choices.map((c,j)=>`<label><input type="radio" name="bankTestQ${i}" value="${j}"> ${c}</label>`).join('')}</div>`}<div class="question-feedback" id="bankTestFeedback${i}" aria-live="polite"></div></article>`).join('')}<div class="test-builder-actions"><button class="primary-btn" onclick="submitBankTest()">${ar?'إنهاء الاختبار وحساب العلامة':fr?'Terminer et calculer la note':'Submit and calculate mark'}</button><button class="secondary-btn" onclick="SM_STUDY_DOWNLOAD.exportCurrent('test')">📥 ${ar?'إنشاء ملف الاختبار مع التصحيح':'Create test + answer file'}</button></div>`;}
function escapeReviewText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function retryIncorrectBankTest(){const test=window.activeBankTest;if(!test)return;const wrong=test.items.filter((q,i)=>test.answers?.[i]?.correct===false);if(!wrong.length)return;window.activeBankTest={...test,items:wrong,submitted:false,startedAt:Date.now(),retryOf:true,answers:{}};renderActiveBankTest();}
function submitBankTest(){
 const test=window.activeBankTest;if(!test||test.submitted)return;
 let correct=0;const topics={},answers={};
 test.items.forEach((q,i)=>{
  let ok=false,entered='';
  if(q.question_type==='numeric'){entered=document.querySelector(`input[name="bankTestQ${i}"]`)?.value||'';ok=!!entered.trim()&&(q.accepted_answers||[]).some(a=>normalizeTypedAnswer(a)===normalizeTypedAnswer(entered));}
  else{const chosen=document.querySelector(`input[name="bankTestQ${i}"]:checked`);entered=chosen?String(q.choices[Number(chosen.value)]??''):'';ok=!!chosen&&Number(chosen.value)===q.answer_index;}
  if(ok)correct++;
  const topic=q.topic||q.lesson||'General';if(!topics[topic])topics[topic]={correct:0,total:0};topics[topic].total++;if(ok)topics[topic].correct++;
  const correctAnswer=q.question_type==='numeric'?(q.accepted_answers||[])[0]??q.solution??'':(q.choices?.[q.answer_index]??q.solution??'');
  answers[i]={correct:ok,entered,correctAnswer};
  const feedback=document.getElementById(`bankTestFeedback${i}`);
  if(feedback){feedback.textContent=(ok?(lang==='ar'?'إجابة صحيحة. ':lang==='fr'?'Réponse correcte. ':'Correct answer. '):(lang==='ar'?'إجابة غير صحيحة. الحل: ':lang==='fr'?'Réponse incorrecte. Solution : ':'Incorrect. Correct answer: ')+correctAnswer+'. ')+(q.explanation||q.why||'');feedback.className='question-feedback '+(ok?'correct':'incorrect');}
 });
 test.writtenResponse=test.integrative?(document.getElementById('integrativeWrittenResponse')?.value||''):'';test.submitted=true;test.answers=answers;
 const mark=Math.round((correct/test.items.length)*2000)/100;
 const ranked=Object.entries(topics).map(([topic,v])=>({topic,rate:v.correct/v.total,count:v.total})).sort((a,b)=>b.rate-a.rate);
 const strengths=ranked.filter(x=>x.rate>=.75).slice(0,3).map(x=>x.topic);
 const weaknesses=ranked.filter(x=>x.rate<.75).sort((a,b)=>a.rate-b.rate).slice(0,3).map(x=>x.topic);
 const learner=activeLearner(),history=readAllBankTestHistory();history.unshift({date:new Date().toISOString().slice(0,10),grade:test.grade,subject:test.subject,term:test.term,correct,total:test.items.length,mark,strengths,weaknesses,learnerId:learner.id,learnerName:learner.name});localStorage.setItem('smSchoolTestHistory',JSON.stringify(history.slice(0,300)));
 recordProgress('tests',test.subject,correct,test.items.length,test.grade);
 const mount=document.getElementById('bankTestMount');const ar=lang==='ar',fr=lang==='fr';
 const title=ar?'نتيجة الاختبار':fr?'Résultat du test':'Test result';
 const strongLabel=ar?'نقاط القوة':fr?'Points forts':'Strengths';const weakLabel=ar?'تحتاج إلى مراجعة':fr?'À réviser':'Needs review';
 const reviewTitle=ar?'مراجعة إجاباتك خطوة بخطوة':fr?'Correction détaillée':'Detailed answer review';
 const yourAnswer=ar?'إجابتك':fr?'Votre réponse':'Your answer';const expected=ar?'الإجابة الصحيحة':fr?'Bonne réponse':'Correct answer';
 const explanation=ar?'التفسير':fr?'Explication':'Explanation';
 const retryLabel=ar?'تدرب مجدداً على إجاباتك الخاطئة':fr?'Réviser mes erreurs':'Practise incorrect answers';
 const review=test.items.map((q,i)=>{const a=answers[i],solutionSteps=(q.solution_steps||[]).map((step,n)=>`<li>${escapeReviewText(step)}</li>`).join('');return `<article class="answer-review-card ${a.correct?'is-correct':'is-wrong'}"><div class="answer-review-head"><b>${ar?'السؤال':fr?'Question':'Question'} ${i+1}</b><span>${a.correct?(ar?'صحيح':fr?'Correct':'Correct'):(ar?'يحتاج مراجعة':fr?'À revoir':'Review needed')}</span></div><p class="answer-review-question">${escapeReviewText(q.question)}</p><p><b>${yourAnswer}:</b> ${escapeReviewText(a.entered|| (ar?'لم تتم الإجابة':fr?'Sans réponse':'Not answered'))}</p><p><b>${expected}:</b> ${escapeReviewText(a.correctAnswer)}</p>${q.explanation||q.why?`<p><b>${explanation}:</b> ${escapeReviewText(q.explanation||q.why)}</p>`:''}${solutionSteps?`<details><summary>${ar?'خطوات الحل':fr?'Étapes de résolution':'Solution steps'}</summary><ol>${solutionSteps}</ol></details>`:''}</article>`}).join('');
 const remedialPlan=buildRemedialPlan(test);
 const integrativeReview=test.integrative?`<section class="panel integrative-model-review"><h4>${ar?'مقارنة الوضعية بالحل النموذجي':fr?'Corrigé modèle de la situation':'Integrative model solution'}</h4><p>${escapeReviewText(test.integrativePaper.model_synthesis)}</p>${test.writtenResponse?`<details><summary>${ar?'إجابتك الكتابية المحفوظة لهذه الجلسة':fr?'Votre réponse écrite':'Your written response'}</summary><p>${escapeReviewText(test.writtenResponse)}</p></details>`:''}<ol>${test.integrativePaper.model_solution.map(x=>`<li><b>${escapeReviewText(x.focus)}:</b> ${escapeReviewText(x.expected_answer)} — ${escapeReviewText(x.reasoning)}</li>`).join('')}</ol><p><b>${ar?'معايير تقييم الجزء الكتابي':fr?'Critères d’autoévaluation':'Written self-review criteria'}:</b> ${test.integrativePaper.written_rubric.map(escapeReviewText).join(' · ')}</p></section>`:'';
 const retryButton=test.items.some((q,i)=>answers[i].correct===false)?`<button class="primary-btn" onclick="retryIncorrectBankTest()">${retryLabel}</button>`:'';
 mount.insertAdjacentHTML('beforeend',`<section class="test-result visible bank-test-result"><h3>${title}: ${mark.toFixed(2)}/20</h3><p>${correct} / ${test.items.length} · ${Math.round(correct/test.items.length*100)}%</p><div class="test-analysis-grid"><div><b>${strongLabel}</b><p>${strengths.map(escapeReviewText).join('، ')|| (ar?'واصل التدريب':fr?'Continuez à pratiquer':'Keep practising')}</p></div><div><b>${weakLabel}</b><p>${weaknesses.map(escapeReviewText).join('، ')||(ar?'لا توجد نقاط ضعف واضحة':fr?'Aucune faiblesse évidente':'No clear weak areas')}</p></div></div>${remedialPlan.html}${integrativeReview}<section class="answer-review"><h4>${reviewTitle}</h4>${review}</section><div class="test-result-actions">${retryButton}<button class="secondary-btn" onclick="renderTestBankHome()">${ar?'اختبار جديد':fr?'Nouveau test':'New test'}</button></div></section>`);
}


function buildRemedialPlan(test){
 const ar=lang==='ar',fr=lang==='fr';
 const wrong=test.items.filter((q,i)=>test.answers?.[i]?.correct===false);
 if(!wrong.length)return {html:`<section class="remedial-plan"><h4>${ar?'خطة المراجعة':fr?'Plan de révision':'Revision plan'}</h4><p>${ar?'أحسنت! لم تسجل أخطاء في هذا الاختبار. حافظ على مستواك بالتدرب دورياً.':fr?'Bravo ! Aucune erreur dans ce test. Entretenez vos acquis avec une pratique régulière.':'Great work! No mistakes in this test. Keep your skills fresh with regular practice.'}</p></section>`,topics:[]};
 const groups=new Map();
 wrong.forEach(q=>{const topic=q.topic||q.lesson||'General';if(!groups.has(topic))groups.set(topic,{topic,count:0,skills:new Set()});const g=groups.get(topic);g.count++;if(q.cognitive_process)g.skills.add(q.cognitive_process)});
 const topics=[...groups.values()].sort((a,b)=>b.count-a.count).slice(0,5).map(g=>({...g,practiceCount:exerciseBankRecords.filter(x=>x.grade===test.grade&&x.subject===test.subject&&((x.topic||x.lesson||'General')===g.topic)).length,skills:[...g.skills]}));
 const action=ar?'ابدأ مراجعة مركزة':fr?'Commencer la révision ciblée':'Start focused practice';
 const title=ar?'خطة علاجية مقترحة':fr?'Plan de remédiation proposé':'Suggested improvement plan';
 const intro=ar?'رتّبنا المراجعة حسب المواضيع التي ظهرت فيها أخطاء. هذه توصيات آلية مبنية على إجابات هذا الاختبار وليست تشخيصاً نهائياً.':fr?'La révision est classée selon les thèmes où des erreurs ont été relevées. Ces conseils automatiques reposent sur ce test et ne constituent pas un diagnostic définitif.':'Revision is prioritized by topics where mistakes occurred. These automatic suggestions are based on this test and are not a definitive diagnosis.';
 const cards=topics.map(g=>`<article class="remedial-topic"><div><b>${escapeReviewText(g.topic)}</b><small>${g.count} ${ar?'أخطاء':fr?'erreurs':'incorrect answers'} · ${g.practiceCount} ${ar?'تمارين متاحة':fr?'exercices disponibles':'practice items available'}</small></div><button class="secondary-btn" ${g.practiceCount?'':'disabled'} onclick="startRemedialTopic(decodeURIComponent('${encodeURIComponent(g.topic)}'))">${action}</button></article>`).join('');
 try{const saved=JSON.parse(localStorage.getItem('smSchoolRemedialPlans')||'[]');saved.unshift({date:new Date().toISOString().slice(0,10),grade:test.grade,subject:test.subject,learnerId:activeLearner().id,topics:topics.map(({topic,count,practiceCount,skills})=>({topic,count,practiceCount,skills}))});localStorage.setItem('smSchoolRemedialPlans',JSON.stringify(saved.slice(0,20)));}catch{}
 return {topics,html:`<section class="remedial-plan"><h4>${title}</h4><p>${intro}</p>${cards}</section>`};
}
function startRemedialTopic(topic){
 const test=window.activeBankTest;if(!test)return;
 grade=test.grade;level=levels.primary.includes(grade)?'primary':levels.middle.includes(grade)?'middle':'secondary';
 localStorage.setItem('smSchoolGrade',grade);localStorage.setItem('smSchoolLevel',level);
 exerciseFilters={term:'all',difficulty:'all',cognitive:'all',topic,search:''};
 renderExerciseBank(test.subject);
}

function renderMathPractice(mode,subject){const bank=subjectPractice[subject]?.[level]||demoBank[level]||demoBank.middle;const items=mode==='tests'?bank:bank.slice(0,2);const title=mode==='tests'?(lang==='ar'?'اختبار تدريبي':'Practice test'):(lang==='ar'?'تمارين تفاعلية':'Practice exercises');$('#pageContent').innerHTML=`${sectionHead(title,grade)}<div class="notice">${t('practiceDemo')}</div><div class="panel learning-panel"><div class="learning-meta"><b>${subject}</b><span>${items.length} ${lang==='ar'?'أسئلة':'questions'}</span></div>${items.map((q,i)=>`<article class="question-card"><h4>${i+1}. ${q.q}</h4>${q.question_type==='numeric'?`<label class="typed-answer"><span>${ar?'اكتب إجابتك':fr?'Votre réponse':'Your answer'}</span><input type="text" inputmode="decimal" autocomplete="off" name="q${i}" placeholder="${ar?'أدخل الإجابة هنا':fr?'Saisir la réponse':'Enter your answer'}"></label>`:`<div class="answer-options">${q.choices.map((c,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${c}</label>`).join('')}</div>`}<div class="question-feedback" id="feedback${i}" aria-live="polite"></div>${mode==='exercises'?`<button class="secondary-btn" onclick="checkOne(${i})">${t('checkAnswer')}</button><button class="text-btn" onclick="showSolution(${i})">${t('showSolution')}</button>`:''}</article>`).join('')}${mode==='tests'?`<button class="primary-btn" onclick="submitTest()">${t('finishTest')}</button><div id="testResult" class="test-result" aria-live="polite"></div>`:''}<button class="text-btn" onclick="render()">${t('backSubjects')}</button></div>`;window.currentPractice={items,mode,subject,answered:{}};}
function normalizeTypedAnswer(value){return String(value??'').trim().toLowerCase().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[،؛]/g,',').replace(/\s+/g,'').replace(/٫/g,'.').replace(/,/g,'.')}
function checkOne(i){const p=window.currentPractice,q=p?.items[i];if(!q)return;let ok=false,missing=false;if(q.question_type==='numeric'){const field=document.querySelector(`input[name="q${i}"]`);const value=field?.value??'';missing=!value.trim();const entered=normalizeTypedAnswer(value);ok=!missing&&(q.accepted_answers||[]).some(a=>normalizeTypedAnswer(a)===entered)}else{const chosen=document.querySelector(`input[name="q${i}"]:checked`);missing=!chosen;ok=!!chosen&&Number(chosen.value)===q.a}const box=$(`#feedback${i}`);if(missing){box.textContent=t('chooseAnswer');box.className='question-feedback warn';return}if(!p.answered[i]){p.answered[i]=true;recordProgress('exercises',p.subject,ok?1:0,1)}p.results=p.results||{};p.results[i]=ok;const key=`smSchoolExerciseMistakes:${p.grade||grade}:${p.subject}`;let misses=[];try{misses=JSON.parse(localStorage.getItem(key)||'[]')}catch{}if(!ok&&!misses.includes(q.id))misses.push(q.id);if(ok)misses=misses.filter(id=>id!==q.id);localStorage.setItem(key,JSON.stringify(misses));box.textContent=(ok?t('correct')+' ':t('incorrect')+' ')+(q.why||q.explanation||'');box.className='question-feedback '+(ok?'correct':'incorrect')}
function showSolution(i){const q=window.currentPractice?.items[i];if(!q)return;const box=$(`#feedback${i}`);const steps=(q.solution_steps||[]).map((step,n)=>`${n+1}) ${step}`).join('\n');box.textContent=t('suggested')+' '+(q.solution||q.choices[q.a])+'.\n'+(steps||q.why);box.className='question-feedback solution';}
function submitTest(){const items=window.currentPractice?.items||[];let score=0;items.forEach((q,i)=>{const chosen=document.querySelector(`input[name="q${i}"]:checked`);const ok=!!chosen&&Number(chosen.value)===q.a;if(ok)score++;const box=$(`#feedback${i}`);box.textContent=(ok?t('correct')+' ':t('incorrect')+' '+q.choices[q.a]+'. ')+q.why;box.className='question-feedback '+(ok?'correct':'incorrect')});const result=$('#testResult');result.textContent=`${lang==='ar'?'نتيجتك':'Score'}: ${score} / ${items.length} — ${Math.round(score/items.length*100)}%`;result.classList.add('visible');localStorage.setItem('smSchoolLastScore',String(score));if(!window.currentPractice.submitted){window.currentPractice.submitted=true;recordProgress('tests',window.currentPractice.subject,score,items.length)}}
function tutorHistoryKey(){return `smSchoolTutorHistory:${activeLearner().id}`}
function readTutorHistory(){try{const rows=JSON.parse(localStorage.getItem(tutorHistoryKey())||'[]');return Array.isArray(rows)?rows.filter(x=>x&&typeof x==='object'&&typeof x.question==='string'&&typeof x.answer==='string'&&x.question.length<=6000&&x.answer.length<=12000).slice(-30):[]}catch{return []}}
function saveTutorTurn(question,answer,task,subject){const rows=readTutorHistory();rows.push({at:new Date().toISOString(),question,answer,task,subject,grade,learnerId:activeLearner().id});localStorage.setItem(tutorHistoryKey(),JSON.stringify(rows.slice(-30)))}
function tutorLearningContext(){const learner=activeLearner(),items=progressStats().items,subjectsMap={};items.forEach(x=>{const k=x.subject||'عام';if(!subjectsMap[k])subjectsMap[k]={correct:0,total:0,count:0};subjectsMap[k].correct+=x.correct||0;subjectsMap[k].total+=x.total||0;subjectsMap[k].count++});return {learner_name:learner.name,learning_context:Object.entries(subjectsMap).map(([subject,v])=>`${subject}: ${v.total?Math.round(v.correct/v.total*100):0}% (${v.count} نشاط)`).join('؛ ').slice(0,1200)}}
function tutor(){const labels=lang==='ar'?{lesson:'شرح درس من الصفر',practice:'إنشاء 5 تمارين',evaluate:'تصحيح إجابة نصية',answer:'اكتب إجابتك هنا (مطلوب للتصحيح)',topic:'اكتب اسم الدرس أو السؤال',history:'سجل هذه المحادثة محفوظ لهذا الطفل فقط',privacy:'عند تفعيل Groq يُرسل السؤال وملخص الأداء التعليمي مباشرة إلى Groq؛ لا يُرسل اسم الطفل.',clear:'مسح المحادثة'}:lang==='fr'?{lesson:'Expliquer une leçon',practice:'Générer 5 exercices',evaluate:'Corriger une réponse rédigée',answer:'Saisissez votre réponse (requise)',topic:'Saisissez le sujet ou la question',history:'Historique enregistré pour cet élève uniquement',privacy:'Avec Groq, la question et un résumé des résultats sont envoyés directement à Groq ; le nom de l’élève n’est pas transmis.',clear:'Effacer la conversation'}:{lesson:'Explain a lesson',practice:'Generate 5 practice questions',evaluate:'Review a written answer',answer:'Enter your answer (required)',topic:'Enter a topic or question',history:'Conversation saved for this learner only',privacy:'When Groq is enabled, the question and a learning summary are sent directly to Groq; the learner name is not sent.',clear:'Clear conversation'};const learner=activeLearner(),historyRows=readTutorHistory();return `${sectionHead(t('ai'),'AI Tutor')}${typeof smAiStatusCard==='function'?smAiStatusCard():`<div class="notice">${t('aiLimited')}</div>`}${typeof tutorServerPanel==='function'?tutorServerPanel():''}<div class="panel tutor-personal"><b>👤 ${escapeReviewText(learner.name)} · ${escapeReviewText(learner.grade)}</b><p>${labels.history}</p></div><div class="chat-box"><div class="chat-head"><div class="avatar">✧</div><div><b>${t('ai')}</b><small><span class="status-dot" style="display:inline-block"></span> ${typeof smAiBadge==='function'?smAiBadge():''}</small></div><button class="text-btn" type="button" onclick="clearTutorHistory()">${labels.clear}</button></div><div class="chat-messages" id="messages"><div class="message bot">${t('aiWelcome')}</div>${historyRows.map(x=>`<div class="message user"><div>${escapeReviewText(x.question)}</div></div><div class="message bot"><div>${escapeReviewText(x.answer)}</div></div>`).join('')}</div><div class="tutor-context"><label>${lang==='ar'?'المادة':lang==='fr'?'Matière':'Subject'}<select id="tutorSubject">${subjectsForCurrentGrade().map(x=>`<option>${x}</option>`).join('')}</select></label><span>${grade}</span></div><form class="tutor-form" id="chatForm"><label class="tutor-mode-label">${lang==='ar'?'نوع المساعدة':lang==='fr'?'Type d’aide':'Help mode'}<select id="tutorTask"><option value="lesson">${labels.lesson}</option><option value="practice">${labels.practice}</option><option value="evaluate">${labels.evaluate}</option></select></label><input id="chatInput" placeholder="${labels.topic}" autocomplete="off" required><textarea id="studentAnswer" class="tutor-answer" placeholder="${labels.answer}" rows="3" hidden></textarea><button class="primary-btn" type="submit">${t('send')}</button></form></div>`}
function clearTutorHistory(){if(!confirm(lang==='ar'?'مسح سجل محادثة هذا الطفل؟':'Clear this learner’s tutor conversation?'))return;localStorage.removeItem(tutorHistoryKey());render()}
function render(){if(!['home','progress','tutor','computing','translate','parents','videos','homeschool'].includes(page))loadHeavyData();const titles={progress:'progress',home:'welcome',library:'books',exercises:'exercises',tests:'tests',tutor:'ai',teacher:'المعلم الذكي',videos:'videos',certificates:'certificates',computing:'computing',translate:'translate',parents:'parents',homeschool:'homeschool',studycenter:'homeschool'};$('#pageTitle').textContent=t(titles[page]);$('#pageContent').innerHTML=page==='home'?home():page==='progress'?progressPage():page==='tutor'?tutor():page==='teacher'&&typeof smartTeacherPage==='function'?smartTeacherPage()+(typeof algerianLessonPlannerPanel182==='function'?algerianLessonPlannerPanel182():'')+(typeof studentProfilePanel==='function'?studentProfilePanel(activeLearner()):'')+(typeof learningDiagnosticPanel==='function'?learningDiagnosticPanel(activeLearner()):'')+(typeof educationalIntelligencePanel==='function'?educationalIntelligencePanel(activeLearner()):''):contentPage(page);if(page==='studycenter'&&typeof studyCenterRender==='function')studyCenterRender();if(window.SM_STUDY_DOWNLOAD&&['exercises','tests'].includes(page))window.SM_STUDY_DOWNLOAD.refreshPanel();if(page==='tutor'){ $('#chatForm').addEventListener('submit',sendChat);{const m=$('#messages');if(m)m.scrollTop=m.scrollHeight} $('#tutorTask').addEventListener('change',e=>{const a=$('#studentAnswer');a.hidden=e.target.value!=='evaluate';a.required=e.target.value==='evaluate'}); }}
async function sendChat(e){if(e)e.preventDefault();const input=$('#chatInput');const msg=(input?.value||lastQuestion).trim();if(!msg)return;const task=$('#tutorTask')?.value||'lesson';const studentAnswer=$('#studentAnswer')?.value||'';if(task==='evaluate'&&!studentAnswer.trim()){toast(lang==='ar'?'اكتب إجابتك أولاً':lang==='fr'?'Saisissez d’abord votre réponse':'Enter your answer first');return}lastQuestion=msg;if(input)input.value='';appendMessage((task==='evaluate'?msg+'\n'+studentAnswer:msg),'user');const waiting=appendMessage(lang==='ar'?'جارٍ التفكير...':lang==='fr'?'Réflexion...':'Thinking...','bot');try{const r=await fetch(`${apiBase()}/api/v1/ai/tutor`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task,message:msg,student_answer:studentAnswer,language:lang,grade,subject:$('#tutorSubject')?.value||'عام',...tutorLearningContext()})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'AI service unavailable');waiting.remove();appendMessage(data.answer||'', 'bot',true);saveTutorTurn(task==='evaluate'?msg+'\n'+studentAnswer:msg,data.answer||'',task,$('#tutorSubject')?.value||'عام')}catch(err){waiting.remove();const off=typeof offlineTutorReply==='function'?await offlineTutorReply(msg,$('#tutorSubject')?.value||'عام',task).catch(()=>null):null;if(off){appendMessage(off,'bot',true);saveTutorTurn(task==='evaluate'?msg+'\n'+studentAnswer:msg,off,task,$('#tutorSubject')?.value||'عام');return}appendMessage((lang==='ar'?'تعذر الاتصال بالأستاذ الذكي: ':lang==='fr'?'Connexion au tuteur impossible : ':'Tutor connection failed: ')+err.message+' — '+t('aiDemo'),'bot',true)}}
function appendMessage(text,who,actions=false){let box=$('#messages'),el=document.createElement('div');el.className='message '+who;const body=document.createElement('div');body.textContent=text;el.appendChild(body);if(actions){const tools=document.createElement('div');tools.className='message-tools';const copy=document.createElement('button');copy.type='button';copy.textContent=lang==='ar'?'نسخ':'Copy';copy.onclick=()=>navigator.clipboard?.writeText(text).then(()=>toast(lang==='ar'?'تم النسخ':'Copied')).catch(()=>toast(lang==='ar'?'تعذر النسخ':'Copy failed'));tools.appendChild(copy);const retry=document.createElement('button');retry.type='button';retry.textContent=lang==='ar'?'إعادة المحاولة':'Retry';retry.onclick=()=>{if(lastQuestion){$('#chatInput').value=lastQuestion;sendChat({preventDefault(){}})}};tools.appendChild(retry);el.appendChild(tools)}box.appendChild(el);box.scrollTop=box.scrollHeight;return el}
function searchYouTube(){let q=$('#videoSearch').value.trim();if(q)window.open('https://www.youtube.com/results?search_query='+encodeURIComponent(q+' شرح '+grade),'_blank','noopener')}
function toast(s){let el=$('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));$('#languageSelect').addEventListener('change',e=>setLanguage(e.target.value));$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));const savedLang=localStorage.getItem('smSchoolLanguage')||'ar';const savedLevel=localStorage.getItem('smSchoolLevel');const savedGrade=localStorage.getItem('smSchoolGrade');if(savedLevel&&levels[savedLevel]){level=savedLevel;grade=levels[level].includes(savedGrade)?savedGrade:levels[level][0];$('#levelSummary').textContent=grade}$('#languageSelect').value=savedLang;setLanguage(savedLang);
let externalExamLibrary={sources:[],records:[],scope:{years:[2022,2023,2024,2025,2026]}};
var heavyDataStarted; function loadHeavyData(){if(heavyDataStarted)return;heavyDataStarted=true;
smFetchJSON('./data/exercise-bank-2026-2027.json').then(data=>{exerciseBankRecords=Array.isArray(data.records)?data.records:[];if(typeof smQualityFilter==='function')exerciseBankRecords=smQualityFilter(exerciseBankRecords);if(page==='exercises')renderExerciseBankHome();if(page==='tests')renderTestBankHome();if(page==='teacher')render()}).catch(()=>{exerciseBankRecords=[]});
fetch('./data/term-exams-2026-2027.json').then(r=>{if(!r.ok)throw new Error('Term exam library unavailable');return r.json()}).then(data=>{termExamPapers=Array.isArray(data.papers)?data.papers:[];if(page==='tests')renderTestBankHome()}).catch(()=>{termExamPapers=[]});
fetch('./data/integrative-assessments-2026-2027.json').then(r=>{if(!r.ok)throw new Error('Integrative assessment library unavailable');return r.json()}).then(data=>{integrativeAssessments=Array.isArray(data.situations)?data.situations:[];if(page==='tests')renderTestBankHome()}).catch(()=>{integrativeAssessments=[]});
}



